def digest(data):
    return hashlib.sha256(data).hexdigest()


def regular(path):
    path = Path(path).absolute()
    if path.resolve() != path or not stat.S_ISREG(path.lstat().st_mode) or path.stat().st_nlink != 1:
        raise ValueError(f"Input is aliased or nonregular: {path}")
    return path.read_bytes()


def frozen(path):
    path = Path(path)
    if path == SSSOM:
        data = gzip.decompress(regular(FIXTURES / "ingredient_mappings.sssom.tsv.gz"))
        expected = CANON_SHA
    elif path == BASELINE:
        data, expected = regular(FIXTURES / "other_cross_record_baseline.tsv"), BASELINE_SHA
    else:
        item = OWNER_META[str(path)]
        data, expected = regular(FIXTURES / "owners" / path.name), item["sha256"]
    if digest(data) != expected:
        raise ValueError(f"Reviewed preimage changed: {path}")
    return data


def evidence_inputs(directory):
    raw = regular(directory / "manifest.json")
    if digest(raw) != SOURCE_SHA:
        raise ValueError("Reviewed primary manifest changed")
    result = {directory / "manifest.json": raw}
    for name, item in json.loads(raw)["files"].items():
        if Path(name).name != name:
            raise ValueError("Primary evidence requires direct filenames")
        data = regular(directory / name)
        if digest(data) != item["sha256"] or len(data) != item["bytes"]:
            raise ValueError(f"Primary evidence changed: {name}")
        result[directory / name] = data
    return result


def render(record):
    with tempfile.TemporaryDirectory(prefix="mim-step5-draft-") as directory:
        path = Path(directory) / "record.yaml"
        write_validated_ingredient(record, path)
        return path.read_bytes()


def propose_sources(owner_bytes, *, timestamp):
    if set(owner_bytes) != set(OWNERS):
        raise ValueError("Exactly three reviewed source owners required")
    parsed = dt.datetime.fromisoformat(timestamp)
    if parsed.utcoffset() != dt.timedelta(0) or parsed.date() < dt.date(2026, 11, 1):
        raise ValueError("Timestamp must be UTC after the source capture")
    evidence = evidence_inputs(ROOT / EVIDENCE)
    result = {}
    for path in OWNERS:
        if owner_bytes[path] != frozen(path):
            raise ValueError(f"Owner differs from reviewed preimage: {path}")
        record = copy.deepcopy(yaml.safe_load(owner_bytes[path]))
        if path == G:
            for entry in record["synonyms"]:
                if entry["synonym_text"] in {"Gro", "glycerolum", "glycyl alcohol"}:
                    if entry["synonym_type"] != "RAW_TEXT" or entry["source"] != "sssom_other_backfill":
                        raise ValueError("Unexpected attributed glycerol alias")
                    entry["synonym_type"] = "REJECTED_LABEL"
            reason = ("#1019: Gro, glycerolum and glycyl alcohol name glycerol, not this phosphate. "
                      "Retyped those existing aliases RAW_TEXT to REJECTED_LABEL; retained original "
                      "source=sssom_other_backfill and prior history. Negative alias evidence (not "
                      "support for the phosphate mapping): " + GLY_URL + " sha256=" +
                      digest(evidence[ROOT / EVIDENCE / "chebi-17754-primary.json"]) + ".")
        elif path == BETA:
            entry = record["synonyms"][0]
            if entry != {"synonym_text": "lactose", "synonym_type": "EXACT_SYNONYM", "source": "merged_from_duplicate_mim_record"}:
                raise ValueError("Unexpected lactose alias")
            entry["synonym_type"] = "RELATED_SYNONYM"
            reason = ("#669: retyped lactose EXACT_SYNONYM to RELATED_SYNONYM, preserving original "
                      "source. Captured OLS LACTOSE hasRelatedSynonym, pdb-ccd: " + BETA_URL +
                      " sha256=" + digest(evidence[ROOT / EVIDENCE / "chebi-36218-ols.json"]) +
                      ". This source correction is separate from export SUPPRESS.")
        else:
            mapping = record["ontology_mapping"]
            if record["identifier"] != "cas:13408-09-8" or mapping["mapping_quality"] != "NARROW_MATCH":
                raise ValueError("Unexpected salt identity or parent quality")
            mapping["ontology_id"], mapping["ontology_label"] = "CHEBI:17270", "glycerol 2-phosphate"
            mapping["evidence"][0]["notes"] = ("Historical evidence superseded by #1020 parent correction; "
                                                  "the original text is preserved verbatim below. " + mapping["evidence"][0]["notes"])
            reason = ("#1020: corrected parent CHEBI:15978 to CHEBI:17270 / glycerol 2-phosphate; "
                      "retained cas:13408-09-8, NARROW_MATCH (published broadMatch), raw labels, counts "
                      "and chemistry. PubChem CID2735049 describes disodium 2-glycerophosphate "
                      "pentahydrate; the CAS-routed and CID-routed responses are byte-identical, one "
                      "evidence payload rather than independent confirmations. The old contradictory "
                      "mapping evidence is explicitly superseded and preserved. DROP the generated-only "
                      "Glycerol 3-phosphate token without inventing a YAML synonym. ")
            for url in PARENT_URLS:
                receipt = next(json.loads(data) for p, data in evidence.items()
                               if p.name.endswith(".receipt.json") and json.loads(data).get("url") == url)
                mapping["evidence"].append({"evidence_type": "MANUAL_CURATION", "source": url,
                    "notes": reason + "Captured response sha256=" + receipt["sha256"] + "."})
            reason += "Correction sources: " + "; ".join(PARENT_URLS) + "."
        reason += " " + APPROVAL + " Policy: " + POLICY
        record_curation_event(record, curator="Codex", action="CORRECTED_OWNED_NAME_SOURCE", changes=reason,
            timestamp=timestamp, previous_status="MAPPED", new_status="MAPPED", llm_assisted=True, llm_model="gpt-6")
        result[path] = render(record)
    return result


def verify_complete_sources(current):
    try:
        stamps = {yaml.safe_load(b)["curation_history"][-1]["timestamp"] for b in current.values()}
    except (KeyError, TypeError, IndexError) as error:
        raise ValueError("Incomplete source correction") from error
    if len(stamps) != 1 or current != propose_sources({p: frozen(p) for p in OWNERS}, timestamp=stamps.pop()):
        raise ValueError("Partial or changed source correction")


def table(raw):
    lines = raw.decode().splitlines(keepends=True)
    while lines and lines[0].startswith("#"):
        lines.pop(0)
    reader = csv.DictReader(io.StringIO("".join(lines)), delimiter="\t")
    rows = list(reader)
    if not reader.fieldnames or any(None in row or None in row.values() for row in rows):
        raise ValueError("Malformed table")
    return reader.fieldnames, rows


def tsv(fields, rows):
    stream = io.StringIO(newline="")
    writer = csv.DictWriter(stream, fieldnames=fields, delimiter="\t", lineterminator="\n")
    writer.writeheader()
    writer.writerows(rows)
    return stream.getvalue().encode()


def remove_tokens(text, forbidden):
    return "|".join(x for x in text.split("|") if x.strip().casefold() not in forbidden)


def promoted_sssom(before, candidate, current, *, kg_sources_by_target):
    """Pure bounded projection. Runtime must separately bind/replay native generation.

    kg_sources_by_target is an exact-source-index result, not a scientific claim.
    It must be bound to the fresh generation input by the future runtime gate.
    """
    if digest(before) != CANON_SHA:
        raise ValueError("Canonical preimage changed")
    verify_complete_sources(current)
    fields, prior = table(before)
    candidate_fields, rows = table(candidate)
    if fields != candidate_fields:
        raise ValueError("Candidate column contract changed")
    old_index = {(r["subject_id"], r["object_id"]): r for r in prior}
    selected = {("MIM:" + p.stem): yaml.safe_load(data) for p, data in current.items()}
    crows = [r for r in rows if r["subject_id"] in selected]
    expected_keys = {k for k in old_index if k[0] in selected}
    expected_keys.remove(("MIM:" + NA.stem, "CHEBI:15978"))
    expected_keys.add(("MIM:" + NA.stem, "CHEBI:17270"))
    if len(crows) != len(expected_keys) or {(r["subject_id"], r["object_id"]) for r in crows} != expected_keys:
        raise ValueError("Expected exactly the five corrected-source candidate rows")
    candidate_index = {(r["subject_id"], r["object_id"]): r for r in crows}
    removals = {x["subject_id"]: {x["token_key"]} for x in PLAN}
    removals["MIM:" + G.stem] = {"gro", "glycerolum", "glycyl alcohol"}
    replacements = {}
    for key, old in old_index.items():
        subject, obj = key
        if subject not in removals:
            continue
        projected = dict(old, other=remove_tokens(old["other"], removals[subject]))
        if subject in selected:
            record = selected[subject]
            new_parent = subject == "MIM:" + NA.stem and obj == "CHEBI:15978"
            target = "CHEBI:17270" if new_parent else obj
            native = candidate_index[(subject, target)]
            expected = dict(projected, mapping_date=record["curation_history"][-1]["timestamp"][:10])
            if new_parent:
                expected.update(object_id=target, object_label="glycerol 2-phosphate", validation_method="")
            expected["comment"] = old["comment"].replace("CHEBI:15978", "CHEBI:17270") if subject == "MIM:" + NA.stem and not new_parent else ""
            kg = list(kg_sources_by_target.get(record["ontology_mapping"]["ontology_id"], ()))
            if not all(x.startswith("kgm:") and "|" not in x for x in kg):
                raise ValueError("Invalid target-specific KG source token")
            expected["source"] = "|".join(["MIM:" + e["source"] for e in record["ontology_mapping"].get("evidence", [])]
                                            + ["MIM:curator=Codex"] + kg)
            if native != expected:
                raise ValueError(f"Candidate differs from bounded native row: {key}")
            projected["mapping_date"] = expected["mapping_date"]
            additions = ["MIM:curator=Codex"]
            if subject == "MIM:" + NA.stem:
                additions = ["MIM:" + u for u in PARENT_URLS] + additions
                projected["comment"] = expected["comment"]
            if new_parent:
                projected.update(object_id=target, object_label="glycerol 2-phosphate", validation_method="",
                    source="|".join(additions + kg),
                    comment=old["comment"] + " [Historical predicate-direction correction on prior CHEBI:15978; #1020 now corrects the parent to CHEBI:17270.]")
            else:
                projected["source"] = "|".join(dict.fromkeys(old["source"].split("|") + additions))
        replacements[key] = projected
    output = []
    for line in before.decode().splitlines(keepends=True):
        if line.startswith("# mapping_set_description: "):
            description = json.loads(line.split(": ", 1)[1])
            marker = "owned-name-policy-v1; suppression-sidecar-required"
            if marker not in description:
                line = "# mapping_set_description: " + json.dumps(description + " " + marker, ensure_ascii=False) + "\n"
        if line.startswith("MIM:"):
            row = next(csv.DictReader(io.StringIO("\t".join(fields) + "\n" + line), delimiter="\t"))
            key = (row["subject_id"], row["object_id"])
            if key in replacements and replacements[key] != row:
                line = tsv(fields, [replacements[key]]).decode().split("\n", 1)[1]
        output.append(line)
    newest = newest_row_date(output)
    if not newest:
        raise ValueError("No canonical row date")
    return "".join(rewrite(output, newest)[0]).encode()


def retired_baseline(before):
    if digest(before) != BASELINE_SHA:
        raise ValueError("Baseline preimage changed")
    selected = {(x["subject_id"], x["token_key"]) for x in PLAN}
    fields, rows = table(before)
    retired = [r for r in rows if (r["subject_id"], r["token"].strip().casefold()) in selected]
    if len(retired) != len(selected):
        raise ValueError("Selected baseline membership changed")
    raw = before.splitlines(keepends=True)
    keep = [raw[0]]
    for line in raw[1:]:
        row = next(csv.DictReader(io.StringIO("\t".join(fields) + "\n" + line.decode()), delimiter="\t"))
        if (row["subject_id"], row["token"].strip().casefold()) not in selected:
            keep.append(line)
    return b"".join(keep)


def canonical_sidecar(promoted, *, candidate_sidecar):
    """Adopt only reviewed SUPPRESS pairs; retain all fresh candidate origins."""
    _, rows = table(promoted)
    fields, diagnostic = table(candidate_sidecar)
    if fields != list(COLS):
        raise ValueError("Diagnostic sidecar contract changed")
    index = {(r["subject_id"], r["token_key"]): r for r in diagnostic}
    if len(index) != len(diagnostic):
        raise ValueError("Duplicate diagnostic pair")
    result = []
    for item in PLAN:
        if item["disposition"] != "SUPPRESS":
            continue
        subject, token = item["subject_id"], item["token_key"]
        if any(r["subject_id"] == subject and token in {s.strip().casefold() for s in r["other"].split("|")} for r in rows):
            raise ValueError("Cannot claim a still-published suppression")
        owners = sorted(x["subject_id"] for x in item["credited_owners"])
        if item["yaml_alias_basis"]:
            row = copy.deepcopy(index[(subject, token)])
            if json.loads(row["owner_subject_ids"]) != owners or row["disposition"] != "SUPPRESS":
                raise ValueError("Diagnostic credited ownership changed")
        else:
            row = {"subject_id": subject, "token_key": token, "token": item["token"], "disposition": "SUPPRESS",
                   "owner_subject_ids": json.dumps(owners), "input_surfaces": json.dumps(["prior_sssom"]),
                   "source_refs": json.dumps(sorted(x["selector"] + "@sha256=" + CANON_SHA for x in item["prior_canonical"]["rows"])),
                   "evidence_refs": json.dumps([POLICY])}
            observed = index.get((subject, token))
            if observed is not None:
                if json.loads(observed["owner_subject_ids"]) != owners or observed["disposition"] != "SUPPRESS":
                    raise ValueError("Diagnostic credited ownership changed")
                for field in ("input_surfaces", "source_refs", "evidence_refs"):
                    row[field] = json.dumps(sorted(set(json.loads(row[field])) | set(json.loads(observed[field]))))
                row["token"] = min(row["token"], observed["token"])
        result.append(row)
    return tsv(COLS, sorted(result, key=lambda x: (x["subject_id"], x["token_key"])))


def source_records(current):
    return [{"source_record": str(p), "shape": "owned_name_source_correction" if p in OWNERS else "export_only_owned_name_suppression",
             "before_yaml_sha256": digest(frozen(p)), "after_yaml_sha256": digest(current.get(p, frozen(p))),
             "change": yaml.safe_load(current[p])["curation_history"][-1]["changes"] if p in OWNERS else "Export-only suppression; source YAML byte-identical, no history event fabricated.",
             "verification": APPROVAL + " " + POLICY} for p in AFFECTED]


def fixed_inputs():
    """Bind the complete small reviewed fixture/decision selection, not mutable globals."""
    path = FIXTURES / "manifest.json"
    raw = regular(path)
    if digest(raw) != FIXTURE_SHA:
        raise ValueError("Immutable fixture manifest changed")
    result = {path: raw}
    declared = json.loads(raw)["files"]
    actual = {str(p.relative_to(FIXTURES)) for p in FIXTURES.rglob("*") if p.is_file()}
    if actual != set(declared) | {"manifest.json"}:
        raise ValueError("Immutable fixture path set changed")
    for name, item in declared.items():
        path = FIXTURES / name
        data = regular(path)
        if digest(data) != item["sha256"] or len(data) != item["bytes"]:
            raise ValueError(f"Immutable fixture changed: {name}")
        result[path] = data
    if (result[FIXTURES / "owner-manifest.json"] != _OWNER_META_BYTES
            or json.loads(_OWNER_META_BYTES) != OWNER_META
            or set(OWNERS) != {Path("data/ingredients/mapped") / (n + ".yaml") for n in _SOURCE_NAMES}
            or set(AFFECTED) != {Path("data/ingredients/mapped") / (n + ".yaml") for n in _AFFECTED_NAMES}):
        raise ValueError("Loaded owner manifest or reviewed owner membership changed")
    decision = REPORT / "decisions/pair-plan.json"
    result[decision] = regular(decision)
    if digest(result[decision]) != PLAN_SHA or json.loads(result[decision]) != PLAN:
        raise ValueError("Reviewed pair plan changed")
    for path in (REPORT / "decisions").glob("*.md"):
        result[path] = regular(path)
    posted = REPORT / "decisions/posted.json"
    result[posted] = regular(posted)
    if digest(result[posted]) != "b1a4631c72fcb50fce91cc1d65d606885819e7a0a9c5b441872b3e6cbcb26019":
        raise ValueError("Posted decision receipt changed")
    for item in json.loads(result[posted]):
        path = REPORT / "decisions" / Path(item["body"]).name
        if digest(result[path]) != item["body_sha256"]:
            raise ValueError("Posted decision body changed")
    return result


def code_inputs():
    result = {p: regular(p) for p in CODE_PATHS}
    if result != _LOADED_CODE:
        raise ValueError("Loaded source-writer code changed")
    return result


def checked_root(root):
    root = Path(root).absolute()
    if root.resolve() != root or not root.is_dir():
        raise ValueError("Repository root must be its original directory")
    return root


def snapshot_sources(root):
    paths = ingredient_paths(root)
    return {p: regular(p) for p in paths}


def ingredient_paths(root):
    """Include ignored/nested owners and reject directory aliases (#1051)."""
    directory = root / "data/ingredients"
    if directory.resolve() != directory:
        raise ValueError("Ingredient directory is aliased")
    result = set()
    for path in directory.rglob("*"):
        if path.is_symlink():
            raise ValueError(f"Ingredient path is aliased: {path}")
        if path.suffix == ".yaml":
            result.add(path)
    return result


def validate_scope(root, inputs, source_paths):
    if ingredient_paths(root) != source_paths:
        raise ValueError("Ingredient owner path set changed")
    for path, expected in inputs.items():
        if regular(path) != expected:
            raise ValueError(f"Bound input changed: {path}")


def before_promotion(root):
    """The first source phase cannot coexist with partial promotion artifacts."""
    if any((root / p).exists() or (root / p).is_symlink() for p in (SIDECAR, PROMOTION_MANIFEST)):
        raise ValueError("Unexpected partial promotion artifacts")


def backups(log):
    return {p: log.with_name(log.stem + ".before-" + p.name) for p in (*OWNERS, SSSOM, BASELINE)}


def completed_receipt(log, expected, root, *, changed, created=()):
    raw = regular(log)
    value = json.loads(raw)
    tx = value.get("transaction") or {}
    if (any(value.get(k) != v for k, v in expected.items()) or value.get("state") != "complete"
            or value.get("applied") is not True or tx.get("applied") is not True
            or set(tx.get("changed", [])) != {str(root / p) for p in changed}
            or len(tx.get("changed", [])) != len(changed)
            or set(tx.get("created", [])) != {str(root / p) for p in created}
            or len(tx.get("created", [])) != len(created) or tx.get("unchanged") != []):
        raise ValueError("Completed receipt does not bind this exact execution")
    return raw


def source_context(root, evidence, current):
    verify_complete_sources(current)
    sources = snapshot_sources(root)
    for p in set(map(Path, OWNER_META)) - set(OWNERS):
        if sources.get(root / p) != frozen(p):
            raise ValueError(f"Unchanged source/name owner changed: {p}")
    inputs = sources | evidence_inputs(evidence) | fixed_inputs() | code_inputs()
    inputs.update({root / p: regular(root / p) for p in (SSSOM, BASELINE)})
    original = dict(inputs)
    original.update({root / p: frozen(p) for p in (*OWNERS, SSSOM, BASELINE)})
    expected = {"phase": "sources", "approval": APPROVAL,
                "timestamp": yaml.safe_load(current[OWNERS[0]])["curation_history"][-1]["timestamp"],
                "evidence_directory": str(evidence), "evidence_manifest_sha256": SOURCE_SHA,
                "input_sha256": {str(p): digest(data) for p, data in original.items()},
                "output_sha256": {str(p): digest(data) for p, data in current.items()},
                "sssom_before_sha256": CANON_SHA, "baseline_before_sha256": BASELINE_SHA,
                "records": source_records(current)}
    return inputs, expected, set(sources)


def source_receipt(root, log):
    root, log = checked_root(root), Path(log).absolute()
    current = {p: regular(root / p) for p in OWNERS}
    value = json.loads(regular(log))
    evidence = Path(value["evidence_directory"])
    inputs, expected, paths = source_context(root, evidence, current)
    inputs[log] = completed_receipt(log, expected, root, changed=set(OWNERS))
    for p, path in backups(log).items():
        data = regular(path)
        if data != frozen(p):
            raise ValueError(f"Source beforeimage changed: {p}")
        inputs[path] = data
    validate_scope(root, inputs, paths)
    return inputs, value


def apply_sources(root, evidence, log, *, apply=False, promotion_log=None):
    root, evidence, log = checked_root(root), Path(evidence).absolute(), Path(log).absolute()
    current = {p: regular(root / p) for p in OWNERS}
    if any(current[p] != frozen(p) for p in OWNERS):
        bound, _ = source_receipt(root, log)
        if all(regular(root / p) == frozen(p) for p in (SSSOM, BASELINE)):
            before_promotion(root)
        else:
            if promotion_log is None:
                raise ValueError("Completed source with changed canonical anchors requires --promotion-log")
            from scripts.promote_owned_name_policy import verify_completed
            verify_completed(root, Path(promotion_log).absolute(), source_log=log)
        return {"applied": False, "changed": False, "approval": APPROVAL}
    if any(regular(root / p) != frozen(p) for p in (SSSOM, BASELINE)):
        raise ValueError("Canonical or baseline anchor changed")
    before_promotion(root)
    current = propose_sources(current, timestamp=dt.datetime.now(dt.timezone.utc).isoformat())
    inputs, result, paths = source_context(root, evidence, current)
    def check():
        validate_scope(root, inputs, paths)
        before_promotion(root)
    check()
    return guarded.publish(root, current, inputs, log,
        {backup: frozen(p) for p, backup in backups(log).items()}, result, apply=apply,
        validate_scope=check)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=ROOT)
    parser.add_argument("--evidence", type=Path)
    parser.add_argument("--log", type=Path, required=True)
    parser.add_argument("--promotion-log", type=Path)
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument("--apply", action="store_true")
    modes.add_argument("--dry-run", action="store_true")
    args = parser.parse_args(argv)
    from plugins.lock_manager import LockManager
    from plugins.repository_settings import RepositorySettings
    root = checked_root(args.root)
    target = RepositorySettings.from_environment().get_target("mediaingredientmech")
    if target.path.resolve() != root:
        raise ValueError("Configured MIM root differs from requested worktree")
    target.open()
    with LockManager().lock("mediaingredientmech", "#669 source corrections"):
        result = apply_sources(root, args.evidence or root / EVIDENCE, args.log,
                               apply=args.apply, promotion_log=args.promotion_log)
    print(json.dumps(result, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Conservatively admit reviewed PRs to an existing native GitHub merge queue.

Standalone, standard-library-only, dry run by default. Reads use GH_TOKEN;
--apply passes GH_MERGE_TOKEN only to the head-pinned enqueue subprocess.
No direct merge, bypass, draft promotion, review, label or comment writes.

GitHub removal events have no PR-head identifier. Retry holds therefore count
complete failed_checks history since the current head's commit timestamp.
The earliest matching tree in PR commits and force-push events prevents empty
commits, tree reverts and same-tree force pushes from clearing a hold. Old/backdated commits can retain conservative holds.
This is admission throttling; GitHub's queue CI remains the integration gate.
"""
from __future__ import annotations

import argparse
import fnmatch
import json
import os
import re
import subprocess
import sys
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

SHA = re.compile(r"[0-9a-f]{40}")
REPOSITORY = re.compile(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+")
HOLD_LABELS = frozenset({"hold", "do-not-merge", "merge-queue:hold", "wip"})
DEFAULT_CACHE_GLOBS = (
    "**/cache/**", "**/caches/**", "**/*_cache/**",
    "**/*cache*.csv", "**/*cache*.tsv",
)
TRUSTED_ASSOCIATIONS = frozenset({"OWNER", "MEMBER", "COLLABORATOR"})
MAX_PAGES = 100  # A bounded read must fail visibly, never claim completeness.


class AdmissionError(ValueError):
    """An API or policy input cannot be established safely."""


@dataclass(frozen=True)
class Rules:
    checks: tuple[tuple[str, int | None], ...]
    review_required: bool


def timestamp(value: Any) -> datetime:
    if not isinstance(value, str):
        raise AdmissionError("missing timestamp")
    try:
        result = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise AdmissionError("invalid timestamp") from exc
    if result.tzinfo is None:
        raise AdmissionError("timestamp has no timezone")
    return result


def require_sha(value: Any) -> str:
    if not isinstance(value, str) or not SHA.fullmatch(value):
        raise AdmissionError("missing or malformed commit SHA")
    return value


def config(path: Path | None) -> tuple[str, ...]:
    if path is None:
        return DEFAULT_CACHE_GLOBS
    try:
        value = json.loads(path.read_text())
    except (OSError, ValueError) as exc:
        raise AdmissionError("cannot read admission configuration") from exc
    if not isinstance(value, dict) or set(value) != {"cache_path_globs"}:
        raise AdmissionError("config must contain only cache_path_globs")
    globs = value["cache_path_globs"]
    if not isinstance(globs, list) or not globs or any(
        not isinstance(item, str) or not item or item.startswith("/")
        or ".." in item.split("/") or any(ord(c) < 32 for c in item)
        for item in globs
    ):
        raise AdmissionError("cache_path_globs must be nonempty relative glob strings")
    return tuple(globs)


class GitHub:
    """Thin gh adapter, injectable in tests; all API methods below are reads."""

    def __init__(self, repository: str):
        if not REPOSITORY.fullmatch(repository):
            raise AdmissionError("repository must be OWNER/REPO")
        self.repository = repository
        self.owner, self.name = repository.split("/")

    def gh(self, args: list[str], *, write: bool = False) -> str:
        env = os.environ.copy()
        token = env.pop("GH_MERGE_TOKEN", "").strip()
        if write:
            if not token:
                raise AdmissionError("--apply requires GH_MERGE_TOKEN")
            env["GH_TOKEN"] = token
        try:
            result = subprocess.run(
                ["gh", *args], env=env, capture_output=True, text=True,
                check=True, timeout=90,
            )
        except (OSError, subprocess.SubprocessError) as exc:
            # Avoid retaining subprocess environments or user-supplied stderr.
            raise AdmissionError("GitHub write failed" if write else "GitHub read failed") from exc
        return result.stdout

    def get(self, endpoint: str) -> Any:
        raw = self.gh(["api", endpoint])
        try:
            return json.loads(raw)
        except ValueError as exc:
            raise AdmissionError("GitHub returned invalid JSON") from exc

    def pages(self, endpoint: str, *, key: str | None = None) -> list[dict]:
        rows: list[dict] = []
        expected: int | None = None
        separator = "&" if "?" in endpoint else "?"
        for page in range(1, MAX_PAGES + 1):
            payload = self.get(f"{endpoint}{separator}per_page=100&page={page}")
            if key is not None:
                if not isinstance(payload, dict) or not isinstance(payload.get("total_count"), int):
                    raise AdmissionError("missing paginated total_count")
                total = payload["total_count"]
                if expected is not None and total != expected:
                    raise AdmissionError("collection changed during pagination")
                expected = total
                payload = payload.get(key)
            if not isinstance(payload, list) or any(not isinstance(row, dict) for row in payload):
                raise AdmissionError("invalid paginated response")
            rows.extend(payload)
            if len(payload) < 100:
                if expected is not None and len(rows) != expected:
                    raise AdmissionError("truncated paginated response")
                return rows
        raise AdmissionError("pagination safety limit reached")

    def graphql(self, body: str, **variables: Any) -> dict:
        query = "query($owner:String!,$name:String!" + "".join(
            f",${key}:{'Int!' if isinstance(value, int) else 'String'}"
            for key, value in variables.items()
        ) + "){repository(owner:$owner,name:$name){" + body + "}}"
        args = ["api", "graphql", "-f", f"query={query}",
                "-f", f"owner={self.owner}", "-f", f"name={self.name}"]
        for key, value in variables.items():
            args.extend(["-F" if isinstance(value, int) else "-f", f"{key}={value}"])
        try:
            payload = json.loads(self.gh(args))
            if payload.get("errors"):
                raise AdmissionError("GraphQL returned errors")
            result = payload["data"]["repository"]
            if not isinstance(result, dict):
                raise AdmissionError("repository unavailable")
            return result
        except (ValueError, KeyError, TypeError) as exc:
            raise AdmissionError("invalid GraphQL response") from exc

    def connection(self, body: str, path: tuple[str, ...], *,
                   filtered_timeline: bool = False, **variables: Any) -> list[dict]:
        rows: list[dict] = []
        seen: set[str] = set()
        total: int | None = None
        cursor = ""
        for _ in range(MAX_PAGES):
            # GitHub rejects an empty cursor, so omit after on the first page.
            fragment = body.replace("AFTER", ",after:$cursor" if cursor else "")
            values = dict(variables)
            if cursor:
                values["cursor"] = cursor
            value = self.graphql(fragment, **values)
            try:
                for key in path:
                    value = value[key]
                nodes = value["nodes"]
                count = value["totalCount"]
                info = value["pageInfo"]
                if not isinstance(nodes, list) or any(not isinstance(n, dict) for n in nodes):
                    raise AdmissionError("invalid connection nodes")
                if not isinstance(count, int) or (total is not None and count != total):
                    raise AdmissionError("connection changed during pagination")
                total = count
                rows.extend(nodes)
                if info["hasNextPage"] is False:
                    # GitHub timeline totalCount includes nonmatching events
                    # even when itemTypes filters nodes. Exhausting pageInfo is
                    # the completeness proof for that API, not node equality.
                    if not filtered_timeline and len(rows) != total:
                        raise AdmissionError("truncated connection")
                    return rows
                cursor = info["endCursor"]
                if not isinstance(cursor, str) or not cursor or cursor in seen:
                    raise AdmissionError("invalid pagination cursor")
                seen.add(cursor)
            except (KeyError, TypeError) as exc:
                raise AdmissionError("unavailable or malformed connection") from exc
        raise AdmissionError("connection safety limit reached")

    def queue(self) -> dict[int, str]:
        nodes = self.connection(
            'mergeQueue(branch:"main"){entries(first:100 AFTER){totalCount '
            'pageInfo{hasNextPage endCursor} nodes{pullRequest{number headRefOid}}}}',
            ("mergeQueue", "entries"),
        )
        result: dict[int, str] = {}
        for row in nodes:
            try:
                number = row["pullRequest"]["number"]
                head = require_sha(row["pullRequest"]["headRefOid"])
                if not isinstance(number, int) or number <= 0 or number in result:
                    raise AdmissionError("invalid or repeated queue entry")
                result[number] = head
            except (KeyError, TypeError) as exc:
                raise AdmissionError("invalid queue entry") from exc
        return result

    def rules(self) -> Rules:
        rules = self.pages(f"repos/{self.repository}/rules/branches/main")
        if not any(rule.get("type") == "merge_queue" for rule in rules):
            raise AdmissionError("main does not require a native merge queue")
        if not any(rule.get("type") == "pull_request" for rule in rules):
            raise AdmissionError("main does not require pull requests")
        checks: set[tuple[str, int | None]] = set()
        reviews = False
        for rule in rules:
            parameters = rule.get("parameters", {})
            if rule.get("type") == "required_status_checks":
                for check in parameters.get("required_status_checks", []):
                    name = check.get("context")
                    app = check.get("integration_id")
                    if not isinstance(name, str) or not name or (app is not None and not isinstance(app, int)):
                        raise AdmissionError("invalid required check rule")
                    checks.add((name, None if app in (None, -1) else app))
            elif rule.get("type") == "pull_request":
                reviews |= bool(parameters.get("required_approving_review_count", 0)
                                or parameters.get("require_code_owner_review")
                                or parameters.get("require_last_push_approval")
                                or parameters.get("required_reviewers"))
        # Rulesets and classic protection can coexist. A null rule means none;
        # an API failure does not mean none.
        classic = self.graphql(
            'ref(qualifiedName:"refs/heads/main"){branchProtectionRule{'
            'requiresApprovingReviews requiresCodeOwnerReviews '
            'requireLastPushApproval requiredStatusChecks{context app{databaseId}}}}'
        )
        try:
            protection = classic["ref"]["branchProtectionRule"]
            if protection:
                reviews |= bool(protection["requiresApprovingReviews"]
                                or protection["requiresCodeOwnerReviews"]
                                or protection["requireLastPushApproval"])
                for check in protection["requiredStatusChecks"]:
                    app = check.get("app")
                    checks.add((check["context"], app["databaseId"] if app else None))
        except (KeyError, TypeError) as exc:
            raise AdmissionError("classic protection is unreadable") from exc
        if not checks:
            raise AdmissionError("no required check contexts established")
        return Rules(tuple(sorted(checks, key=lambda item: (item[0], item[1] or -1))), reviews)

    def integrity_reason(self) -> str:
        commit = self.get(f"repos/{self.repository}/commits/main")
        head = require_sha(commit.get("sha"))
        runs, _ = self.checks(head)
        matching = [run for run in runs if run.get("name") == "merge-integrity"
                    and run.get("app", {}).get("id") == 15368]
        if not matching:
            return "main_integrity_pending: current main has no trusted integrity check"
        if any(run.get("head_sha") != head or run.get("status") != "completed"
               for run in matching):
            return "main_integrity_pending: current main integrity check is pending"
        if any(run.get("conclusion") != "success" for run in matching):
            return "main_integrity_failed: current main integrity check did not pass"
        return ""

    def open_prs(self) -> list[dict]:
        return self.pages(f"repos/{self.repository}/pulls?state=open&base=main&sort=created&direction=asc")

    def pr(self, number: int) -> dict:
        value = self.get(f"repos/{self.repository}/pulls/{number}")
        graph = self.graphql(
            "pullRequest(number:$number){headRefOid mergeable mergeStateStatus reviewDecision}",
            number=number,
        ).get("pullRequest")
        if not isinstance(value, dict) or not isinstance(graph, dict):
            raise AdmissionError("PR is unreadable")
        if value.get("head", {}).get("sha") != graph.get("headRefOid"):
            raise AdmissionError("PR head changed during read")
        return dict(value, **graph)

    def reviews(self, number: int) -> list[dict]:
        return self.pages(f"repos/{self.repository}/pulls/{number}/reviews")

    def checks(self, head: str) -> tuple[list[dict], list[dict]]:
        return (
            self.pages(f"repos/{self.repository}/commits/{head}/check-runs?filter=latest", key="check_runs"),
            self.pages(f"repos/{self.repository}/commits/{head}/statuses"),
        )

    def files(self, number: int, expected: int) -> list[dict]:
        rows = self.pages(f"repos/{self.repository}/pulls/{number}/files")
        if any(not isinstance(row.get("filename"), str) or not row["filename"] for row in rows):
            raise AdmissionError("changed-file name unavailable")
        if len(rows) != expected or len({row["filename"] for row in rows}) != len(rows):
            raise AdmissionError("changed files are truncated or duplicated")
        return rows

    def history(self, number: int) -> list[dict]:
        return self.connection(
            'pullRequest(number:$number){timelineItems(first:100 AFTER,'
            'itemTypes:[REMOVED_FROM_MERGE_QUEUE_EVENT,HEAD_REF_FORCE_PUSHED_EVENT]){totalCount '
            'pageInfo{hasNextPage endCursor} nodes{__typename '
            '... on RemovedFromMergeQueueEvent{createdAt reason} '
            '... on HeadRefForcePushedEvent{createdAt '
            'beforeCommit{oid committedDate tree{oid}} '
            'afterCommit{oid committedDate tree{oid}}}}}}',
            ("pullRequest", "timelineItems"), filtered_timeline=True, number=number,
        )

    def commits(self, number: int, expected: int) -> list[dict]:
        rows = self.pages(f"repos/{self.repository}/pulls/{number}/commits")
        if len(rows) != expected:
            raise AdmissionError("PR commit history is truncated")
        return rows

    def enqueue(self, number: int, head: str, pull_request_id: str) -> None:
        if not isinstance(pull_request_id, str) or not pull_request_id:
            raise AdmissionError("PR node identity unavailable")
        require_sha(head)
        # Unlike `gh pr merge`, this operation cannot become a direct merge
        # if an administrator removes the queue between our read and write.
        query = (
            "mutation($id:ID!,$head:GitObjectID!){enqueuePullRequest(input:{"
            "pullRequestId:$id,expectedHeadOid:$head}){mergeQueueEntry{"
            "pullRequest{id number headRefOid isInMergeQueue}}}}"
        )
        raw = self.gh(["api", "graphql", "-f", f"query={query}",
                       "-f", f"id={pull_request_id}", "-f", f"head={head}"], write=True)
        try:
            payload = json.loads(raw)
            if payload.get("errors"):
                raise AdmissionError("queue-only mutation failed")
            pr = payload["data"]["enqueuePullRequest"]["mergeQueueEntry"]["pullRequest"]
            if (pr["id"] != pull_request_id or pr["number"] != number
                    or pr["headRefOid"] != head or pr["isInMergeQueue"] is not True):
                raise AdmissionError("queue admission receipt does not match verified PR")
        except (ValueError, KeyError, TypeError) as exc:
            raise AdmissionError("queue admission could not be confirmed") from exc


def basic_reason(pr: dict) -> str:
    if pr.get("state") != "open" or pr.get("base", {}).get("ref") != "main":
        return "not an open PR targeting main"
    if pr.get("draft") is not False:
        return "draft or unknown draft state"
    if not isinstance(pr.get("assignees"), list) or any(
        assignee.get("type") != "Bot" for assignee in pr["assignees"]
    ):
        return "human or unknown assignee holds this PR"
    if not isinstance(pr.get("labels"), list):
        return "labels unreadable"
    if any(str(label.get("name", "")).casefold() in HOLD_LABELS for label in pr["labels"]):
        return "hold label"
    return ""


def review_reason(reviews: list[dict], pr: dict, rules: Rules) -> str:
    latest: dict[str, dict] = {}
    requested_changes: set[str] = set()
    for review in sorted(reviews, key=lambda row: row.get("id", 0)):
        user = review.get("user") or {}
        login = user.get("login")
        if not isinstance(login, str) or not login:
            return "review author unavailable"
        # Pending reviews are private drafts, not a replacement decision.
        identity = login.casefold()
        state = review.get("state")
        if state == "CHANGES_REQUESTED":
            requested_changes.add(identity)
        elif state in {"APPROVED", "DISMISSED"}:
            requested_changes.discard(identity)
        if state != "PENDING":
            latest[identity] = review
    if requested_changes:
        return "changes requested"
    if rules.review_required and pr.get("reviewDecision") != "APPROVED":
        return "GitHub review requirements are not satisfied"
    for review in latest.values():
        if (review.get("state") == "APPROVED"
                and review.get("commit_id") == pr["headRefOid"]
                and review.get("author_association") in TRUSTED_ASSOCIATIONS
                and review.get("user", {}).get("login") != pr.get("user", {}).get("login")):
            return ""
    return "no trusted latest approval on the current head"


def check_reason(runs: list[dict], statuses: list[dict], rules: Rules, head: str) -> str:
    latest_status: dict[str, dict] = {}
    for status in sorted(statuses, key=lambda row: row.get("id", 0)):
        latest_status[status.get("context", "")] = status
    for name, app in rules.checks:
        matching = [run for run in runs if run.get("name") == name
                    and (app is None or run.get("app", {}).get("id") == app)]
        legacy = latest_status.get(name) if app is None else None
        if not matching and legacy is None:
            return f"required check missing from its trusted source: {name}"
        if any(run.get("head_sha") != head or run.get("status") != "completed"
               or run.get("conclusion") != "success" for run in matching):
            return f"required check is not successful on the current head: {name}"
        if legacy is not None and legacy.get("state") != "success":
            return f"required status is not successful: {name}"
    return ""


def cache_path(path: str, globs: tuple[str, ...]) -> bool:
    return any(fnmatch.fnmatchcase(path, pattern)
               or (pattern.startswith("**/") and fnmatch.fnmatchcase(path, pattern[3:]))
               for pattern in globs)


def cache_claims(files: list[dict], globs: tuple[str, ...]) -> set[str]:
    claims: set[str] = set()
    for row in files:
        paths = {row.get("filename"), row.get("previous_filename")} - {None}
        if any(not isinstance(path, str) for path in paths):
            raise AdmissionError("invalid changed-file path")
        matches = {path for path in paths if cache_path(path, globs)}
        if not matches:
            continue
        patch = row.get("patch")
        if not isinstance(patch, str) or not patch:
            raise AdmissionError("shared cache patch missing")
        # File reservations do not need row parsing, but validating the patch
        # prevents missing/truncated API evidence from silently passing.
        lines = patch.splitlines()
        additions = sum(line.startswith("+") for line in lines)
        deletions = sum(line.startswith("-") for line in lines)
        if (additions != row.get("additions") or deletions != row.get("deletions")
                or not any(line.startswith("@@ ") for line in lines)):
            raise AdmissionError("shared cache patch truncated or malformed")
        claims.update(matches)
    return claims


def retry_reason(commits: list[dict], events: list[dict], head: str, now: datetime) -> str:
    if not commits or commits[-1].get("sha") != head:
        raise AdmissionError("PR commit history does not end at current head")
    try:
        tree = require_sha(commits[-1]["commit"]["tree"]["sha"])
        dates = [timestamp(row["commit"]["committer"]["date"])
                 for row in commits if row["commit"]["tree"]["sha"] == tree]
        # Force-pushed commits may no longer appear in the PR's current commit
        # list. Preserve their tree/date evidence from the immutable timeline;
        # otherwise amending only a timestamp would replenish retry attempts.
        for event in events:
            if event.get("__typename") == "HeadRefForcePushedEvent":
                for key in ("beforeCommit", "afterCommit"):
                    previous = event[key]
                    require_sha(previous["oid"])
                    previous_tree = require_sha(previous["tree"]["oid"])
                    previous_date = timestamp(previous["committedDate"])
                    if previous_tree == tree:
                        dates.append(previous_date)
        if any(date > now for date in dates):
            raise AdmissionError("head has a future commit timestamp")
        since = min(dates)
        failures = 0
        for event in events:
            when = timestamp(event.get("createdAt"))
            if when > now:
                raise AdmissionError("queue event has a future timestamp")
            if event.get("__typename") == "HeadRefForcePushedEvent":
                continue
            if not isinstance(event.get("reason"), str) or not event["reason"]:
                raise AdmissionError("queue ejection reason is unavailable")
            if event.get("reason") == "failed_checks" and when >= since:
                failures += 1
    except (KeyError, TypeError) as exc:
        raise AdmissionError("commit or ejection history is unreadable") from exc
    return f"held after {failures} failed-check queue ejections on unchanged content" if failures >= 2 else ""


def eligibility(api: GitHub, number: int, rules: Rules, globs: tuple[str, ...],
                *, expected_head: str | None = None) -> tuple[dict, set[str], str]:
    pr = api.pr(number)
    reason = basic_reason(pr)
    head = require_sha(pr.get("headRefOid"))
    if expected_head is not None and head != expected_head:
        return pr, set(), "head changed during admission"
    if reason:
        return pr, set(), reason
    if pr.get("mergeable") != "MERGEABLE" or pr.get("mergeStateStatus") != "CLEAN":
        return pr, set(), "PR is not mergeable with satisfied branch rules"
    reason = review_reason(api.reviews(number), pr, rules)
    if reason:
        return pr, set(), reason
    reason = check_reason(*api.checks(head), rules, head)
    if reason:
        return pr, set(), reason
    reason = retry_reason(api.commits(number, pr["commits"]), api.history(number), head,
                          datetime.now(timezone.utc))
    if reason:
        return pr, set(), reason
    claims = cache_claims(api.files(number, pr["changed_files"]), globs)
    # Review/check/file/history reads are not atomic. Ensure they still refer
    # to the same head and no human hold arrived before returning eligibility.
    final = api.pr(number)
    if final.get("headRefOid") != head:
        return final, set(), "head changed during admission"
    reason = basic_reason(final)
    if reason:
        return final, set(), reason
    if final.get("mergeable") != "MERGEABLE" or final.get("mergeStateStatus") != "CLEAN":
        return final, set(), "branch eligibility changed during admission"
    if rules.review_required and final.get("reviewDecision") != "APPROVED":
        return final, set(), "review requirements changed during admission"
    return final, claims, ""


def run(api: GitHub, *, apply: bool, max_admissions: int, globs: tuple[str, ...]) -> dict:
    report: dict = {"repository": api.repository, "mode": "apply" if apply else "dry-run",
                    "rows": [], "errors": [], "admitted": 0}
    reserved: dict[str, int] = {}
    claimed_by_queue: dict[tuple[int, str], set[str]] = {}
    write_outcome_unknown = False
    try:
        rules = api.rules()
        api.queue()  # An absent/unreadable queue stops even an empty sweep.
        integrity = api.integrity_reason()
        report["main_integrity"] = integrity or "passed"
        prs = api.open_prs()
        prs.sort(key=lambda row: (timestamp(row["created_at"]), row["number"]))
    except (AdmissionError, KeyError, TypeError) as exc:
        report["errors"].append(str(exc))
        return report
    for listed in prs:
        number = listed.get("number")
        row = {"number": number, "status": "held", "reason": ""}
        report["rows"].append(row)
        if not isinstance(number, int) or number <= 0:
            row.update(status="error", reason="invalid PR number")
            continue
        if write_outcome_unknown:
            row["reason"] = "previous enqueue outcome unknown; sweep stopped"
            continue
        if integrity:
            row["reason"] = integrity
            continue
        if report["admitted"] >= max_admissions:
            row["reason"] = "admission limit reached"
            continue
        if reason := basic_reason(listed):
            row["reason"] = reason
            continue
        write_started = False
        try:
            # The queue can change after every admission. A queue member with
            # unreadable files blocks the sweep, as its reservations are unknown.
            queued = api.queue()
            if number in queued:
                row.update(status="already_queued", reason="already in native queue")
                continue
            active = dict(reserved)
            for queued_number, queued_head in queued.items():
                key = (queued_number, queued_head)
                if key not in claimed_by_queue:
                    queued_pr = api.pr(queued_number)
                    if queued_pr.get("headRefOid") != queued_head:
                        raise AdmissionError("queued PR changed while reading cache claims")
                    claimed_by_queue[key] = cache_claims(
                        api.files(queued_number, queued_pr["changed_files"]), globs)
                for path in claimed_by_queue[key]:
                    active[path] = queued_number
            pr, claims, reason = eligibility(api, number, rules, globs)
            if reason:
                row["reason"] = reason
                continue
            collisions = sorted(claims & active.keys())
            if collisions:
                row["reason"] = "shared cache reserved by " + ", ".join(
                    f"#{active[path]} ({path})" for path in collisions[:5])
                continue
            # Re-read rules and queue immediately before the final verification;
            # no fallback when the queue disappears or policies change.
            if reason := api.integrity_reason():
                row["reason"] = reason
                continue
            if api.rules() != rules or api.queue() != queued:
                row["reason"] = "rules or queue changed; reconsider next sweep"
                continue
            pr, final_claims, reason = eligibility(
                api, number, rules, globs, expected_head=pr["headRefOid"])
            if reason or final_claims != claims:
                row["reason"] = reason or "cache changes changed during admission"
                continue
            if api.queue() != queued:
                row["reason"] = "queue changed before admission"
                continue
            # Expensive history/file reads above can overlap human reviews or
            # a main integrity failure. Re-read these volatile gates at the
            # actual action boundary, including zero-required-review repos.
            final = api.pr(number)
            if final.get("headRefOid") != pr["headRefOid"]:
                row["reason"] = "head changed at admission boundary"
                continue
            reason = basic_reason(final)
            if not reason and (final.get("mergeable") != "MERGEABLE"
                               or final.get("mergeStateStatus") != "CLEAN"):
                reason = "branch eligibility changed at admission boundary"
            if not reason:
                reason = review_reason(api.reviews(number), final, rules)
            if not reason:
                reason = check_reason(*api.checks(pr["headRefOid"]), rules, pr["headRefOid"])
            if not reason:
                reason = api.integrity_reason()
            if reason:
                row["reason"] = reason
                continue
            row["head"] = pr["headRefOid"]
            if apply:
                write_started = True
                api.enqueue(number, pr["headRefOid"], pr["node_id"])
            row.update(status="enqueued" if apply else "would_enqueue", reason="all admission gates satisfied")
            report["admitted"] += 1
            reserved.update(dict.fromkeys(claims, number))
        except (AdmissionError, KeyError, TypeError) as exc:
            write_outcome_unknown |= write_started
            reason = ("enqueue outcome unknown; sweep stopped: " if write_started else "") + str(exc)
            row.update(status="error", reason=reason)
    return report


def bounded_count(value: str) -> int:
    parsed = int(value)
    if not 1 <= parsed <= 50:
        raise argparse.ArgumentTypeError("must be between 1 and 50")
    return parsed


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--repository", required=True)
    parser.add_argument("--apply", action="store_true")
    parser.add_argument("--report", type=Path)
    parser.add_argument("--max-admissions", type=bounded_count, default=3)
    parser.add_argument("--config", type=Path)
    args = parser.parse_args(argv)
    try:
        if args.apply and not os.environ.get("GH_MERGE_TOKEN", "").strip():
            raise AdmissionError("--apply requires GH_MERGE_TOKEN")
        result = run(GitHub(args.repository), apply=args.apply,
                     max_admissions=args.max_admissions, globs=config(args.config))
        output = json.dumps(result, indent=2) + "\n"
        if args.report:
            args.report.write_text(output)
        print(output, end="")
        return int(bool(result["errors"] or any(row["status"] == "error" for row in result["rows"])))
    except (AdmissionError, OSError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Build/check the public ingredient site from a complete current source checkout."""

from __future__ import annotations

import argparse
import hashlib
import json
import shutil
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
sys.path.insert(0, str(ROOT / "scripts"))

import browser_export  # noqa: E402

from mediaingredientmech import render_ingredient_pages as render  # noqa: E402
from mediaingredientmech.schema_site import write_schema_site  # noqa: E402

PACKAGE_ROOT = Path(render.__file__).resolve().parent


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def source_files(repo: Path) -> list[Path]:
    return sorted(
        p
        for status in ("mapped", "unmapped")
        for p in (repo / "data" / "ingredients" / status).glob("*.yaml")
    )


def build_inputs(repo: Path) -> dict[str, str]:
    files = {
        "builder": Path(__file__),
        "renderer": Path(render.__file__),
        "exporter": Path(browser_export.__file__),
    }
    files.update(
        {
            "template/" + p.relative_to(render.TEMPLATES_DIR).as_posix(): p
            for p in render.TEMPLATES_DIR.rglob("*")
            if p.is_file()
        }
    )
    # Local renderer/exporter dependencies affect scientific labels and URLs too.
    # Exclude interpreter caches, which are unrelated to the generated content.
    files.update(
        {
            "package/" + p.relative_to(PACKAGE_ROOT).as_posix(): p
            for p in PACKAGE_ROOT.rglob("*")
            if p.is_file() and "__pycache__" not in p.parts and p.suffix != ".pyc"
        }
    )
    files.update(
        {
            "docs/" + name: repo / "docs" / name
            for name in (
                "index.html",
                "browser.html",
                "theme-toggle.js",
                "map-record-navigation.js",
                "ingredient_umap.html",
                "ingredient_graph.html",
            )
        }
    )
    for optional_doc in ("404.html", "text_map.html"):
        opt_path = repo / "docs" / optional_doc
        if opt_path.exists():
            files["docs/" + optional_doc] = opt_path
    return {name: digest(path) for name, path in sorted(files.items())}


def check_site(repo: Path, output: Path) -> None:
    """Refuse missing pages, stale sources/templates, and incomplete catalog links."""
    ingredient_root = repo / "data" / "ingredients"
    sources = {p.relative_to(ingredient_root).as_posix(): p for p in source_files(repo)}
    if not sources:
        raise ValueError("No ingredient sources found")
    receipt = json.loads((output / "records" / "build.json").read_text())
    if receipt["build_inputs"] != build_inputs(repo):
        raise ValueError("Site templates or build inputs are stale")
    catalog = json.loads((output / "data" / "ingredients.json").read_text())
    catalog_rows = catalog["ingredients"]
    if len(catalog_rows) != len(sources) or {r["source_file"] for r in catalog_rows} != set(
        sources
    ):
        raise ValueError("Catalog does not cover every ingredient source exactly once")
    records = receipt["records"]
    if set(records) != set(sources):
        raise ValueError("Record manifest does not cover every ingredient source")
    expected_pages = set()
    for row in catalog_rows:
        source = sources[row["source_file"]]
        expected = f"records/ingredient/{render.slug_for({}, source)}.html"
        if row.get("detail_page") != expected or expected in expected_pages:
            raise ValueError(f"Non-unique or incorrect detail URL: {row['source_file']}")
        expected_pages.add(expected)
        record = records[row["source_file"]]
        if record != {
            "source_sha256": digest(source),
            "page": expected,
            "page_sha256": digest(output / expected),
        }:
            raise ValueError(f"Missing or stale ingredient page: {row['source_file']}")
    actual_pages = {
        p.relative_to(output).as_posix()
        for p in (output / "records" / "ingredient").rglob("*.html")
    }
    if actual_pages != expected_pages:
        raise ValueError("Missing or orphaned ingredient pages")
    required_assets = {
        "data/ingredients.json",
        "records/index.html",
        "records/style.css",
        "index.html",
        "browser.html",
        "theme-toggle.js",
    }
    for optional_doc in ("404.html", "text_map.html"):
        if (repo / "docs" / optional_doc).exists():
            required_assets.add(optional_doc)
    required_assets.update(
        p.relative_to(output).as_posix() for p in (output / "schema").glob("*.html")
    )
    required_assets.add("map-record-navigation.js")
    if not (output / "schema" / "index.html").exists():
        raise ValueError("Missing rendered schema reference")
    if set(receipt["assets"]) != required_assets:
        raise ValueError("Incomplete site assets")
    for name, checksum in receipt["assets"].items():
        if digest(output / name) != checksum:
            raise ValueError(f"Changed generated site asset: {name}")


def build_site(repo: Path, output: Path) -> int:
    """Stage, render all records, validate, then promote a new output directory."""
    if output.exists():
        raise ValueError(f"Output already exists: {output}; choose a fresh build directory")
    files = source_files(repo)
    if not files:
        raise ValueError("No ingredient sources found")
    urls = [render.slug_for({}, p) for p in files]
    if len(set(urls)) != len(urls):
        raise ValueError("Ingredient source names collide after slug normalization")
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix=".mim-site-", dir=output.parent) as temporary:
        stage = Path(temporary) / "site"
        shutil.copytree(repo / "docs", stage)
        # Never carry previously generated record pages forward into a fresh build.
        if (stage / "records").exists():
            raise ValueError("docs/records must not contain generated site output")
        browser_export.export_ingredients_to_json(
            repo / "data" / "ingredients", stage / "data" / "ingredients.json"
        )
        env = render.make_env()
        index = stage / "records"
        records = {}
        successful = []
        for source in files:
            status, ingredient, slug = render.render_one(
                env, source, index / "ingredient", force=True
            )
            if status != "rendered":
                raise ValueError(f"Cannot render {source.name}: {status}")
            page = f"records/ingredient/{slug}.html"
            key = source.relative_to(repo / "data" / "ingredients").as_posix()
            records[key] = {
                "source_sha256": digest(source),
                "page": page,
                "page_sha256": digest(stage / page),
            }
            successful.append({"ingredient": ingredient, "slug": slug})
        render.write_index(index, successful)
        shutil.copyfile(render.TEMPLATES_DIR / "style.css", index / "style.css")
        schema_assets = write_schema_site(
            PACKAGE_ROOT / "schema" / "mediaingredientmech.yaml", stage / "schema"
        )
        (stage / ".nojekyll").touch()
        optional_assets = tuple(
            name for name in ("404.html", "text_map.html") if (repo / "docs" / name).exists()
        )
        asset_names = (
            "data/ingredients.json",
            "records/index.html",
            "records/style.css",
            "index.html",
            "browser.html",
            "theme-toggle.js",
            *optional_assets,
        )
        receipt = {
            "build_inputs": build_inputs(repo),
            "records": records,
            "assets": {
                name: digest(stage / name)
                for name in (*asset_names, "map-record-navigation.js", *schema_assets)
            },
        }
        (index / "build.json").write_text(json.dumps(receipt, indent=2) + "\n")
        check_site(repo, stage)
        stage.rename(output)
    return len(files)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=ROOT / "site")
    parser.add_argument("--check", type=Path, help="check an existing built artifact")
    args = parser.parse_args()
    try:
        if args.check:
            check_site(ROOT, args.check.resolve())
            print("Ingredient site is complete and current")
        else:
            count = build_site(ROOT, args.output.resolve())
            print(f"Built and verified {count} public ingredient pages")
    except (ValueError, OSError, KeyError, TypeError) as error:
        print(f"Site build failed: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Flag agent-instruction files that name recipes or paths which no longer exist.

Skills, commands and `/goal` prompts are executable in practice: an agent reads
them and does what they say. When they drift they do not fail loudly like code —
they quietly send the next agent down a path that no longer exists, or worse, one
that is actively wrong. `.claude/commands/ground-or-propose-ingredient.md` kept
recommending `just export-individual` / `just aggregate-collections` "to keep
per-record files and collections in sync" long after that pairing was identified
as the mechanism which silently reverted 55 curation events (#148); it had to be
corrected twice, both times because a human happened to notice (#167, #179).

This is the mechanical version of noticing. It reports three kinds of drift:

* `just <recipe>` naming a recipe the justfile does not define;
* a long option in a documented Python CLI example that the referenced script
  does not declare;
* a repo-relative path (`scripts/x.py`, `data/y.yaml`, …) that does not exist.

Deliberately narrow, because a false positive in a docs check is how the check
gets ignored:

* only references inside a code span or fenced block count — prose like "just the
  collection" is not a recipe reference;
* a path must contain a `/`, so a bare "mapped_ingredients.yaml" in prose is not
  treated as a path claim;
* paths resolve against the repo root AND the containing file's directory, since
  skills reference their own `reference/*.md` relatively;
* existence means TRACKED IN GIT, not present on disk. Checking the filesystem
  makes the result depend on the developer's local layout — a sibling
  `../culturebotai-claw` checkout and generated artifacts like
  `reports/label_drift.tsv` both exist locally and not in CI, so the check
  reported clean on one machine and failed on another. A guard whose answer
  depends on who runs it is the failure mode this whole check exists to catch;
* a `../` reference points outside the repo and cannot be verified here. Those
  are counted and reported, never failed — silently dropping them would hide how
  much is unchecked.

Legitimate references that this cannot verify — a sibling repo's recipe, a file
the reader is told to create, a deliberate mention of something removed — are
declared in `conf/instruction_refs.yaml` with a reason, or suppressed inline with
`<!-- refcheck: ignore -->` on the same line.

Exit codes: 0 = clean (or severity=warn), 1 = findings with severity=error,
2 = configuration/usage error.
"""

from __future__ import annotations

import argparse
import ast
import re
import shlex
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path

import yaml

REPO_ROOT = Path(__file__).resolve().parent.parent
DEFAULT_CONFIG = REPO_ROOT / "conf" / "instruction_refs.yaml"

INLINE_SUPPRESS = "<!-- refcheck: ignore -->"

CODE_SPAN = re.compile(r"`([^`\n]+)`")
JUST_CALL = re.compile(r"^just\s+([a-z0-9][a-z0-9-]*)")
# A path claim needs a directory separator and a known extension: this is a
# reference to a file in the repo, not an ordinary filename mentioned in prose.
PATH_CLAIM = re.compile(
    r"^([A-Za-z0-9_.][A-Za-z0-9_./-]*/[A-Za-z0-9_./-]+\.(?:py|ya?ml|tsv|json|sh|md|j2))$"
)


@dataclass(frozen=True)
class Finding:
    kind: str  # "recipe" | "path" | "option"
    path: str  # file containing the stale reference
    line: int
    ref: str
    command: str | None = None

    def __str__(self) -> str:
        if self.kind == "recipe":
            what = f"just {self.ref}"
        elif self.kind == "option":
            what = f"{self.command} {self.ref}"
        else:
            what = self.ref
        return f"{self.path}:{self.line}  {what}"


def tracked_paths(root: Path) -> set[str]:
    """Repo-relative paths git tracks.

    Deliberately not `Path.exists()`: the filesystem includes untracked build
    artifacts and whatever sibling repos happen to be checked out, so a
    filesystem check answers differently on a developer machine than in CI.
    """
    proc = subprocess.run(
        ["git", "ls-files"], cwd=root, capture_output=True, text=True, check=False
    )
    if proc.returncode != 0:
        raise SystemExit(
            f"`git ls-files` failed (exit {proc.returncode}); cannot verify path "
            f"references.\n{proc.stderr.strip()}"
        )
    return set(proc.stdout.split())


# A recipe definition: a name at column 0, optional parameters (which may carry
# `=` defaults), then `:` — but not `:=`, which is a variable assignment.
RECIPE_DEF = re.compile(r"^([a-z0-9][a-z0-9-]*)[^:\n]*:(?!=)")


def known_recipes(root: Path) -> set[str]:
    """Recipe names the justfile defines, parsed from the file itself.

    Deliberately not `just --list`: that would make the check unrunnable wherever
    `just` is not installed — including this repo's own pytest workflow, where it
    failed for exactly that reason. Verified to produce the identical 55-recipe
    set as `just --list` on the current justfile.
    """
    justfile = root / "justfile"
    if not justfile.is_file():
        raise SystemExit(f"No justfile at {justfile}; cannot verify recipe references.")
    return {
        match.group(1)
        for line in justfile.read_text(encoding="utf-8").splitlines()
        if (match := RECIPE_DEF.match(line))
    }


def _references(text: str):
    """Yield (line_no, code_span) for every code span and fenced-block line."""
    in_fence = False
    for line_no, line in enumerate(text.splitlines(), 1):
        if line.lstrip().startswith("```"):
            in_fence = not in_fence
            continue
        if INLINE_SUPPRESS in line:
            continue
        if in_fence:
            yield line_no, line.strip()
        else:
            for match in CODE_SPAN.finditer(line):
                yield line_no, match.group(1).strip()


def _logical_commands(lines: list[tuple[int, str]]):
    """Join shell lines ending in a backslash into one documented command."""
    start = 0
    parts: list[str] = []
    for line_no, raw_line in lines:
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if not parts:
            start = line_no
        continued = line.endswith("\\")
        parts.append(line[:-1].rstrip() if continued else line)
        if not continued:
            yield start, " ".join(parts)
            parts = []
    if parts:
        yield start, " ".join(parts)


def _cli_invocations(text: str):
    """Yield documented command lines from code spans and fenced blocks."""
    fence_lines: list[tuple[int, str]] = []
    in_fence = False
    for line_no, line in enumerate(text.splitlines(), 1):
        if line.lstrip().startswith("```"):
            if in_fence:
                yield from _logical_commands(fence_lines)
                fence_lines = []
            in_fence = not in_fence
            continue
        if INLINE_SUPPRESS in line:
            continue
        if in_fence:
            fence_lines.append((line_no, line))
        else:
            for match in CODE_SPAN.finditer(line):
                yield line_no, match.group(1).strip()
    if fence_lines:
        yield from _logical_commands(fence_lines)


def known_cli_options(script: Path) -> set[str]:
    """Extract argparse/click options without importing arbitrary scripts."""
    try:
        tree = ast.parse(script.read_text(encoding="utf-8"), filename=str(script))
    except (OSError, SyntaxError):
        return set()

    options = {"--help"}  # supplied automatically by argparse and Click
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        function = node.func
        function_name = (
            function.attr if isinstance(function, ast.Attribute) else getattr(function, "id", "")
        )
        if function_name not in {"option", "add_argument"}:
            continue
        for arg in node.args:
            if not isinstance(arg, ast.Constant) or not isinstance(arg.value, str):
                continue
            if not arg.value.startswith("--"):
                continue
            # Click supports paired declarations such as --color/--no-color.
            options.update(part for part in arg.value.split("/") if part.startswith("--"))
    return options


def _documented_cli(command: str) -> tuple[str, set[str]] | None:
    """Parse a Python script invocation into its path and documented options."""
    try:
        tokens = shlex.split(command, comments=True)
    except ValueError:
        return None
    python_index = next(
        (index for index, token in enumerate(tokens) if token in {"python", "python3"}),
        None,
    )
    if python_index is None or python_index + 1 >= len(tokens):
        return None
    script = tokens[python_index + 1].removeprefix("./")
    if not script.startswith("scripts/") or not script.endswith(".py"):
        return None
    options = {
        token.split("=", 1)[0] for token in tokens[python_index + 2 :] if token.startswith("--")
    }
    return script, options


def scan_file(
    path: Path, root: Path, recipes: set[str], tracked: set[str]
) -> tuple[list[Finding], int]:
    """Return (findings, out_of_repo_references_not_verified)."""
    findings: list[Finding] = []
    unverifiable = 0
    rel = path.relative_to(root).as_posix()
    text = path.read_text(encoding="utf-8")
    for line_no, span in _references(text):
        recipe = JUST_CALL.match(span)
        if recipe and recipe.group(1) not in recipes:
            findings.append(Finding("recipe", rel, line_no, recipe.group(1)))
        claim = PATH_CLAIM.match(span)
        if claim:
            target = claim.group(1)
            if target.startswith("../"):
                # Outside the repo — unverifiable from here, so never a finding.
                unverifiable += 1
                continue
            # Repo-relative, or relative to the file itself (skills reference
            # their own reference/*.md that way).
            here = (path.parent / target).resolve()
            as_local = here.relative_to(root).as_posix() if here.is_relative_to(root) else None
            if target not in tracked and (as_local is None or as_local not in tracked):
                findings.append(Finding("path", rel, line_no, target))

    for line_no, command in _cli_invocations(text):
        invocation = _documented_cli(command)
        if invocation is None:
            continue
        script, documented_options = invocation
        if script not in tracked:
            # A command-prefixed path (``python scripts/x.py``) is not a bare
            # PATH_CLAIM span, so the path pass above cannot see it. Treat the
            # missing executable itself as the finding; option validation only
            # makes sense after the script resolves (#453 review).
            findings.append(Finding("path", rel, line_no, script))
            continue
        supported_options = known_cli_options(root / script)
        for option in sorted(documented_options - supported_options):
            findings.append(Finding("option", rel, line_no, option, script))
    return findings, unverifiable


def load_config(config_path: Path) -> dict:
    if not config_path.is_file():
        raise SystemExit(f"Config not found: {config_path}")
    cfg = yaml.safe_load(config_path.read_text()) or {}
    for key in ("targets", "severity"):
        if key not in cfg:
            raise SystemExit(f"Config {config_path} is missing required key: {key}")
    return cfg


def collect_targets(root: Path, globs: list[str], tracked: set[str]) -> list[Path]:
    """Files to scan: the configured globs, intersected with what git tracks.

    The glob on its own answers differently on a developer machine than in CI —
    the same reason `tracked_paths` exists. That reasoning had been applied to
    the *targets* of references but not to the set of files scanned for them, so
    an untracked scratch file in the working tree was checked locally and
    invisible in CI. The check could then fail on a file no reviewer can see,
    or pass in CI while failing for whoever has that file (#406).

    An untracked file is not part of the repo's instructions, so a reference
    inside one is not this check's business.
    """
    seen: dict[Path, None] = {}
    for pattern in globs:
        for path in sorted(root.glob(pattern)):
            if not path.is_file():
                continue
            try:
                rel = path.relative_to(root).as_posix()
            except ValueError:
                continue
            if rel in tracked:
                seen.setdefault(path, None)
    return list(seen)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, default=DEFAULT_CONFIG)
    parser.add_argument(
        "--severity",
        choices=("warn", "error"),
        default=None,
        help="Override the config's severity. `error` exits 1 on any finding.",
    )
    args = parser.parse_args(argv)

    cfg = load_config(args.config)
    severity = args.severity or cfg["severity"]
    ignored_recipes = {
        entry["name"] for entry in (cfg.get("ignore_recipes") or []) if "name" in entry
    }
    ignored_paths = {entry["path"] for entry in (cfg.get("ignore_paths") or []) if "path" in entry}

    recipes = known_recipes(REPO_ROOT)
    tracked = tracked_paths(REPO_ROOT)
    targets = collect_targets(REPO_ROOT, cfg["targets"], tracked)
    if not targets:
        raise SystemExit(f"No instruction files matched: {cfg['targets']}")

    findings: list[Finding] = []
    unverifiable = 0
    for path in targets:
        file_findings, out_of_repo = scan_file(path, REPO_ROOT, recipes, tracked)
        unverifiable += out_of_repo
        for finding in file_findings:
            if finding.kind == "recipe" and finding.ref in ignored_recipes:
                continue
            if finding.kind == "path" and finding.ref in ignored_paths:
                continue
            findings.append(finding)

    print(f"Scanned {len(targets)} agent-instruction file(s) against {len(recipes)} recipes.")
    if unverifiable:
        # Say what was not checked, rather than let a green result imply it was.
        print(
            f"  ({unverifiable} `../` reference(s) point outside the repo and were not verified.)"
        )
    if not findings:
        print("OK: every referenced recipe, path, and Python CLI option exists.")
        return 0

    stale_recipes = [f for f in findings if f.kind == "recipe"]
    stale_paths = [f for f in findings if f.kind == "path"]
    stale_options = [f for f in findings if f.kind == "option"]
    if stale_recipes:
        print(f"\nRecipes that no longer exist ({len(stale_recipes)}):")
        for finding in stale_recipes:
            print(f"  {finding}")
    if stale_paths:
        print(f"\nPaths that no longer exist ({len(stale_paths)}):")
        for finding in stale_paths:
            print(f"  {finding}")
    if stale_options:
        print(f"\nCLI options the referenced script does not support ({len(stale_options)}):")
        for finding in stale_options:
            print(f"  {finding}")

    print(
        "\nEach of these tells the next agent to run or read something that is not "
        "there.\nFix the reference, or — if it is a sibling repo's recipe, a file the "
        "reader creates,\nor a deliberate mention of something removed — declare it in "
        f"{args.config.relative_to(REPO_ROOT)} with a reason,\nor add "
        f"`{INLINE_SUPPRESS}` to the line."
    )

    if severity == "error":
        return 1
    print("\n(severity=warn: reporting only, not failing the build)")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Reject reviewed bad identities in the unified export, without external deps.

See docs/UNIFIED_MAPPING_REJECTIONS.md for identity and exact-label scopes.
"""

from __future__ import annotations

import argparse
import csv
from pathlib import Path
import re
import unicodedata

ROOT = Path(__file__).resolve().parents[1]
LEDGER = ROOT / "mappings/unified_mapping_rejections.tsv"
ARTIFACT = ROOT / "UNIFIED_INGREDIENT_MAPPING.tsv"
IDENTITY_COLUMNS = ("chebi_id", "culturemech_term_id", "mim_id", "kg_microbe_node_id", "cas_rn")
REJECTION_ID = re.compile(r"[A-Za-z][A-Za-z0-9.]*:[A-Za-z0-9][A-Za-z0-9._~-]*\Z")


def _label_key(name: str) -> str:
    return unicodedata.normalize("NFC", name).strip().casefold()


def check(artifact: Path = ARTIFACT, ledger: Path = LEDGER) -> list[str]:
    """Verify rejections even when a stale producer regenerates and stamps a TSV."""
    problems = []
    try:
        with ledger.open(encoding="utf-8", newline="") as handle:
            reader = csv.DictReader(handle, delimiter="\t")
            columns = ["ingredient_name", "rejected_id", "mim_id", "reason"]
            if reader.fieldnames != columns:
                return [f"{ledger}: invalid rejection-ledger columns"]
            raw_rejections = list(reader)
        rejections = []
        seen = set()
        for row in raw_rejections:
            if (
                None in row
                or any(row.get(c) is None for c in columns)
                or any(not row[c].strip() for c in columns if c != "mim_id")
            ):
                return [f"{ledger}: incomplete rejection"]
            row = {key: value.strip() for key, value in row.items()}
            key = (
                (row["mim_id"], row["rejected_id"])
                if row["mim_id"]
                else ("source_label", _label_key(row["ingredient_name"]), row["rejected_id"])
            )
            if key in seen or not REJECTION_ID.fullmatch(row["rejected_id"]) or row["mim_id"].startswith("UNMAPPED"):
                return [f"{ledger}: duplicate or invalid rejection"]
            if row["rejected_id"] == row["mim_id"]:
                return [f"{ledger}: rejected ID equals corrected identity"]
            seen.add(key)
            rejections.append(row)
        with artifact.open(encoding="utf-8", newline="") as handle:
            reader = csv.DictReader(handle, delimiter="\t")
            if not {"ingredient_name", *IDENTITY_COLUMNS}.issubset(reader.fieldnames or []):
                return [f"{artifact}: missing identity columns"]
            for line, row in enumerate(reader, 2):
                if None in row or any(row[c] is None for c in ("ingredient_name", *IDENTITY_COLUMNS)):
                    return [f"{artifact}:{line}: malformed export row"]
                for rejected in rejections:
                    same_label = _label_key(row["ingredient_name"]) == _label_key(rejected["ingredient_name"])
                    same_identity = bool(rejected["mim_id"]) and row["mim_id"] == rejected["mim_id"]
                    if not (same_label or same_identity):
                        continue
                    if same_label and rejected["mim_id"] and not same_identity:
                        problems.append(f"{artifact}:{line}: {row['ingredient_name']} lost its curated identity {rejected['mim_id']}")
                    for column in IDENTITY_COLUMNS:
                        if row[column] == rejected["rejected_id"]:
                            problems.append(f"{artifact}:{line}: {row['ingredient_name']} republishes rejected {row[column]} in {column}")
    except (OSError, UnicodeError, csv.Error) as error:
        problems.append(str(error))
    return problems


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--artifact", type=Path, default=ARTIFACT)
    parser.add_argument("--ledger", type=Path, default=LEDGER)
    args = parser.parse_args()
    problems = check(args.artifact, args.ledger)
    if problems:
        print("\n".join(problems))
        return 1
    print("Unified export respects reviewed identity rejections.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Check a Mech's governed files against an immutable claw revision.

This file is deliberately standalone and uses only the Python standard
library.  The canonical copy is vendored into every Mech, but it obtains the
artifact set from claw's single manifest at the exact commit recorded in
``scripts/.vendored_canon_ref``.  No provider or model API is involved.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import stat
import subprocess
import sys
import time
import unicodedata
import urllib.error
import urllib.parse
import urllib.request
from collections.abc import Callable, Mapping, Sequence
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from types import MappingProxyType
from typing import Any

CANONICAL_REPOSITORY = "CultureBotAI/culturebotai-claw"
CANONICAL_MANIFEST_PATH = "src/kg_microbe_governance/vendored_artifacts.json"
DEFAULT_PIN_PATH = "scripts/.vendored_canon_ref"
DEFAULT_TIMEOUT_SECONDS = 5.0
MAX_DOWNLOAD_BYTES = 8 * 1024 * 1024

_SHA_PATTERN = re.compile(r"^[0-9a-f]{40}$")
_SHA256_PATTERN = re.compile(r"^[0-9a-f]{64}$")
_KEY_PATTERN = re.compile(r"^[a-z][a-z0-9_]*$")
_PATH_PART_PATTERN = re.compile(r"^[A-Za-z0-9._-]+$")
_GITHUB_PATTERN = re.compile(
    r"^[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?/"
    r"[A-Za-z0-9_.-]+$"
)


class GovernanceError(ValueError):
    """Raised when a governance input cannot be trusted."""


class CanonicalFetchError(GovernanceError):
    """Raised for a potentially transient canonical-source fetch failure."""


@dataclass(frozen=True)
class Consumer:
    key: str
    github: str
    package_path: str


@dataclass(frozen=True)
class Artifact:
    artifact_id: str
    source: str
    target: str
    consumers: tuple[str, ...]
    sha256: str
    mode: int

    def applies_to(self, consumer_key: str) -> bool:
        return not self.consumers or consumer_key in self.consumers


@dataclass(frozen=True)
class GovernanceManifest:
    canonical_repository: str
    pin_path: str
    consumers: Mapping[str, Consumer]
    artifacts: tuple[Artifact, ...]

    def consumer_for(self, identity: str) -> Consumer:
        lowered = identity.lower()
        for consumer in self.consumers.values():
            if consumer.key.lower() == lowered or consumer.github.lower() == lowered:
                return consumer
        known = ", ".join(
            consumer.github for consumer in self.consumers.values()
        )
        raise GovernanceError(
            f"Unknown Mech repository identity {identity!r}; expected one of: {known}"
        )

    def artifacts_for(self, consumer: Consumer) -> tuple[Artifact, ...]:
        return tuple(
            artifact
            for artifact in self.artifacts
            if artifact.applies_to(consumer.key)
        )


def _reject_duplicate_pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise GovernanceError(f"Governance manifest has duplicate key {key!r}")
        result[key] = value
    return result


def _mapping(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise GovernanceError(f"{label} must be an object")
    return value


def _strict_keys(
    value: Mapping[str, Any], allowed: set[str], required: set[str], label: str
) -> None:
    unknown = set(value) - allowed
    missing = required - set(value)
    if unknown:
        raise GovernanceError(
            f"{label} has unknown keys: {', '.join(sorted(unknown))}"
        )
    if missing:
        raise GovernanceError(
            f"{label} is missing keys: {', '.join(sorted(missing))}"
        )


def _string(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip() or value != value.strip():
        raise GovernanceError(f"{label} must be a non-empty trimmed string")
    if any(character in value for character in ("\x00", "\r", "\n", "\t")):
        raise GovernanceError(f"{label} contains a control character")
    return value


def _relative_path(value: Any, label: str, *, template: bool = False) -> str:
    path = _string(value, label)
    if unicodedata.normalize("NFC", path) != path:
        raise GovernanceError(f"{label} must use canonical Unicode spelling")
    if "\\" in path:
        raise GovernanceError(f"{label} must use POSIX separators")
    if path.startswith(":"):
        raise GovernanceError(f"{label} must not use Git pathspec magic")
    if template and (
        path.count("{package_path}") > 1
        or any(
            "{package_path}" in part and part != "{package_path}"
            for part in path.split("/")
        )
    ):
        raise GovernanceError(
            f"{label} may contain {{package_path}} once as a complete path segment"
        )
    probe = path.replace("{package_path}", "package") if template else path
    if "{" in probe or "}" in probe:
        raise GovernanceError(f"{label} contains an unsupported template field")
    pure = PurePosixPath(probe)
    if (
        pure.is_absolute()
        or not pure.parts
        or pure.as_posix() != probe
        or any(part in {"", ".", ".."} for part in pure.parts)
    ):
        raise GovernanceError(f"{label} must be a safe canonical relative path")
    if any(part.casefold() == ".git" for part in pure.parts):
        raise GovernanceError(f"{label} must not address Git metadata")
    if any(
        part != "{package_path}" and not _PATH_PART_PATTERN.fullmatch(part)
        for part in path.split("/")
    ):
        raise GovernanceError(
            f"{label} contains characters unsafe for Git and canonical URLs"
        )
    if any(any(character in part for character in "*?[]") for part in pure.parts):
        raise GovernanceError(f"{label} must not contain glob syntax")
    return path


def _portable_parts(path: str) -> tuple[str, ...]:
    return tuple(
        unicodedata.normalize("NFC", part).casefold()
        for part in PurePosixPath(path).parts
    )


def _paths_conflict(left: str, right: str) -> bool:
    """Detect aliases and file/descendant conflicts on portable filesystems."""

    left_parts = _portable_parts(left)
    right_parts = _portable_parts(right)
    shared = min(len(left_parts), len(right_parts))
    return left_parts[:shared] == right_parts[:shared]


def parse_manifest(data: bytes) -> GovernanceManifest:
    """Parse and validate the canonical JSON manifest fail-closed."""

    try:
        document = json.loads(data.decode("utf-8"), object_pairs_hook=_reject_duplicate_pairs)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise GovernanceError(f"Unable to parse governance manifest: {exc}") from exc
    root = _mapping(document, "Governance manifest")
    _strict_keys(
        root,
        {"version", "canonical_repository", "pin_path", "consumers", "artifacts"},
        {"version", "canonical_repository", "pin_path", "consumers", "artifacts"},
        "Governance manifest",
    )
    if (
        not isinstance(root["version"], int)
        or isinstance(root["version"], bool)
        or root["version"] != 1
    ):
        raise GovernanceError("Governance manifest version must be integer 1")
    canonical_repository = _string(
        root["canonical_repository"], "canonical_repository"
    )
    if canonical_repository != CANONICAL_REPOSITORY:
        raise GovernanceError(
            "Governance manifest canonical_repository does not match the "
            f"checker authority {CANONICAL_REPOSITORY}"
        )
    pin_path = _relative_path(root["pin_path"], "pin_path")

    raw_consumers = _mapping(root["consumers"], "consumers")
    if not raw_consumers:
        raise GovernanceError("consumers must not be empty")
    consumers: dict[str, Consumer] = {}
    github_identities: set[str] = set()
    package_paths: set[str] = set()
    for raw_key, raw_consumer in raw_consumers.items():
        key = _string(raw_key, "consumer key")
        if not _KEY_PATTERN.fullmatch(key):
            raise GovernanceError(f"Invalid consumer key {key!r}")
        consumer_mapping = _mapping(raw_consumer, f"consumers.{key}")
        _strict_keys(
            consumer_mapping,
            {"github", "package_path"},
            {"github", "package_path"},
            f"consumers.{key}",
        )
        github = _string(consumer_mapping["github"], f"consumers.{key}.github")
        if (
            not _GITHUB_PATTERN.fullmatch(github)
            or github.rsplit("/", 1)[-1] in {".", ".."}
        ):
            raise GovernanceError(
                f"consumers.{key}.github must be an owner/repository identity"
            )
        package_path = _relative_path(
            consumer_mapping["package_path"], f"consumers.{key}.package_path"
        )
        if github.lower() in github_identities:
            raise GovernanceError(f"Duplicate consumer GitHub identity {github!r}")
        if package_path in package_paths:
            raise GovernanceError(f"Duplicate consumer package path {package_path!r}")
        github_identities.add(github.lower())
        package_paths.add(package_path)
        consumers[key] = Consumer(key, github, package_path)

    raw_artifacts = root["artifacts"]
    if not isinstance(raw_artifacts, list) or not raw_artifacts:
        raise GovernanceError("artifacts must be a non-empty array")
    artifacts: list[Artifact] = []
    artifact_ids: set[str] = set()
    targets_by_consumer: dict[str, list[str]] = {
        key: [pin_path] for key in consumers
    }
    for index, raw_artifact in enumerate(raw_artifacts):
        label = f"artifacts[{index}]"
        artifact_mapping = _mapping(raw_artifact, label)
        _strict_keys(
            artifact_mapping,
            {"id", "source", "target", "consumers", "sha256", "mode"},
            {"id", "source", "target", "consumers", "sha256", "mode"},
            label,
        )
        artifact_id = _string(artifact_mapping["id"], f"{label}.id")
        if not _KEY_PATTERN.fullmatch(artifact_id):
            raise GovernanceError(f"{label}.id is not a valid identifier")
        if artifact_id in artifact_ids:
            raise GovernanceError(f"Duplicate artifact id {artifact_id!r}")
        artifact_ids.add(artifact_id)
        source = _relative_path(artifact_mapping["source"], f"{label}.source")
        if not source.startswith("src/kg_microbe_governance/artifacts/"):
            raise GovernanceError(
                f"{label}.source must be under the canonical artifact directory"
            )
        target = _relative_path(
            artifact_mapping["target"], f"{label}.target", template=True
        )
        raw_scope = artifact_mapping["consumers"]
        if raw_scope == "all":
            scope: tuple[str, ...] = ()
        elif isinstance(raw_scope, list) and raw_scope:
            scope_values = [
                _string(value, f"{label}.consumers") for value in raw_scope
            ]
            if len(scope_values) != len(set(scope_values)):
                raise GovernanceError(f"{label}.consumers contains duplicates")
            unknown_consumers = set(scope_values) - set(consumers)
            if unknown_consumers:
                raise GovernanceError(
                    f"{label}.consumers names unknown consumers: "
                    f"{', '.join(sorted(unknown_consumers))}"
                )
            scope = tuple(scope_values)
        else:
            raise GovernanceError(
                f"{label}.consumers must be 'all' or a non-empty key array"
            )
        digest = _string(artifact_mapping["sha256"], f"{label}.sha256")
        if not _SHA256_PATTERN.fullmatch(digest):
            raise GovernanceError(f"{label}.sha256 must be 64 lowercase hex digits")
        mode_text = _string(artifact_mapping["mode"], f"{label}.mode")
        if mode_text not in {"0644", "0755"}:
            raise GovernanceError(f"{label}.mode must be 0644 or 0755")
        mode = int(mode_text, 8)
        artifact = Artifact(artifact_id, source, target, scope, digest, mode)
        for consumer in consumers.values():
            if not artifact.applies_to(consumer.key):
                continue
            expanded = expand_target(artifact, consumer)
            for existing in targets_by_consumer[consumer.key]:
                if _paths_conflict(existing, expanded):
                    raise GovernanceError(
                        f"Conflicting targets {existing!r} and {expanded!r} "
                        f"for consumer {consumer.key}"
                    )
            targets_by_consumer[consumer.key].append(expanded)
        artifacts.append(artifact)

    for consumer in consumers.values():
        if not any(artifact.applies_to(consumer.key) for artifact in artifacts):
            raise GovernanceError(f"Consumer {consumer.key} has no governed artifacts")
    return GovernanceManifest(
        canonical_repository=canonical_repository,
        pin_path=pin_path,
        consumers=MappingProxyType(consumers),
        artifacts=tuple(artifacts),
    )


def expand_target(artifact: Artifact, consumer: Consumer) -> str:
    """Expand the sole supported target placeholder and revalidate the result."""

    expanded = artifact.target.replace("{package_path}", consumer.package_path)
    return _relative_path(expanded, f"expanded target for {artifact.artifact_id}")


def read_pin(root: Path, pin_path: str = DEFAULT_PIN_PATH) -> str:
    """Read an exact immutable commit pin from a regular, non-symlink file."""

    root = root.resolve()
    relative = _relative_path(pin_path, "pin path")
    path = _safe_local_file(root, relative)
    try:
        metadata = path.lstat()
    except OSError as exc:
        raise GovernanceError(f"Unable to read canonical pin {relative}: {exc}") from exc
    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISREG(metadata.st_mode):
        raise GovernanceError(f"Canonical pin {relative} must be a regular file")
    if metadata.st_mode & 0o111:
        raise GovernanceError(f"Canonical pin {relative} must not be executable")
    if metadata.st_mode & (stat.S_IWGRP | stat.S_IWOTH):
        raise GovernanceError(
            f"Canonical pin {relative} must not be group/other-writable"
        )
    try:
        content = path.read_text(encoding="ascii")
    except (OSError, UnicodeError) as exc:
        raise GovernanceError(f"Unable to read canonical pin {relative}: {exc}") from exc
    pin = content.strip()
    if not _SHA_PATTERN.fullmatch(pin):
        raise GovernanceError(
            f"Canonical pin {relative} must contain exactly one 40-character SHA"
        )
    if content not in {pin, pin + "\n"}:
        raise GovernanceError(f"Canonical pin {relative} contains extra content")
    return pin


def raw_url(ref: str, relative_path: str) -> str:
    if not _SHA_PATTERN.fullmatch(ref):
        raise GovernanceError("Canonical ref must be a full 40-character SHA")
    safe_path = _relative_path(relative_path, "canonical path")
    return (
        "https://raw.githubusercontent.com/"
        f"{CANONICAL_REPOSITORY}/{ref}/{safe_path}"
    )


def fetch_url(url: str, timeout: float = DEFAULT_TIMEOUT_SECONDS) -> bytes:
    """Fetch a size- and wall-time-bounded canonical artifact."""

    if timeout <= 0:
        raise GovernanceError("Canonical fetch timeout must be positive")
    request = urllib.request.Request(url, headers={"User-Agent": "kg-microbe-governance/1"})
    deadline = time.monotonic() + timeout
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            final_url = urllib.parse.urlsplit(response.geturl())
            if (
                final_url.scheme != "https"
                or final_url.hostname != "raw.githubusercontent.com"
            ):
                destination = (
                    f"{final_url.scheme or '<missing-scheme>'}://"
                    f"{final_url.hostname or '<missing-host>'}"
                )
                raise CanonicalFetchError(
                    "Canonical fetch redirected outside raw.githubusercontent.com: "
                    f"{destination}"
                )
            declared = response.headers.get("Content-Length")
            if declared is not None and (
                int(declared) < 0 or int(declared) > MAX_DOWNLOAD_BYTES
            ):
                raise CanonicalFetchError(
                    f"Canonical artifact exceeds {MAX_DOWNLOAD_BYTES} bytes"
                )
            data = bytearray()
            while len(data) <= MAX_DOWNLOAD_BYTES:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise CanonicalFetchError(
                        f"Canonical artifact fetch exceeded {timeout:g} seconds"
                    )
                # CPython's HTTPS response exposes the active socket here. Set
                # each blocking read to the remaining total budget; the
                # fallback still checks the deadline between chunks.
                try:
                    response.fp.raw._sock.settimeout(max(0.001, remaining))
                except AttributeError:
                    pass
                chunk = response.read(
                    min(64 * 1024, MAX_DOWNLOAD_BYTES + 1 - len(data))
                )
                if not chunk:
                    break
                data.extend(chunk)
    except (OSError, ValueError, urllib.error.URLError) as exc:
        raise CanonicalFetchError(
            f"Unable to fetch canonical artifact {url}: {exc}"
        ) from exc
    if len(data) > MAX_DOWNLOAD_BYTES:
        raise CanonicalFetchError(
            f"Canonical artifact exceeds {MAX_DOWNLOAD_BYTES} bytes"
        )
    return bytes(data)


def _git_environment() -> dict[str, str]:
    """Return an environment with repository-routing Git variables removed."""

    environment = {
        key: value
        for key, value in os.environ.items()
        if not key.upper().startswith("GIT_")
    }
    # Replacement refs can make object inspection differ from what the recorded
    # commit would push. Promisor lazy-fetches would also evade the explicitly
    # bounded canonical HTTPS path. Both must fail closed for local evidence.
    environment["GIT_NO_REPLACE_OBJECTS"] = "1"
    environment["GIT_NO_LAZY_FETCH"] = "1"
    return environment


def _run_git(root: Path, arguments: Sequence[str], *, timeout: float = 5) -> str:
    try:
        result = subprocess.run(
            ["git", "-c", "core.fsmonitor=false", *arguments],
            cwd=root,
            check=True,
            capture_output=True,
            text=True,
            timeout=timeout,
            env=_git_environment(),
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise GovernanceError(f"Git repository inspection failed at {root}") from exc
    return result.stdout


def _normalize_remote(remote: str) -> str:
    patterns = (
        r"^https://github\.com/(?P<identity>[^/]+/[^/]+?)(?:\.git)?$",
        r"^git@github\.com:(?P<identity>[^/]+/[^/]+?)(?:\.git)?$",
        r"^ssh://git@github\.com/(?P<identity>[^/]+/[^/]+?)(?:\.git)?$",
    )
    for pattern in patterns:
        match = re.fullmatch(pattern, remote)
        if match:
            return match.group("identity")
    raise GovernanceError("Unsupported or non-GitHub origin URL")


def _remote_identity(root: Path) -> str:
    remotes: list[str] = []
    for arguments in (
        ("remote", "get-url", "--all", "origin"),
        ("remote", "get-url", "--push", "--all", "origin"),
    ):
        output = _run_git(root, arguments)
        values = [line.strip() for line in output.splitlines() if line.strip()]
        if not values:
            raise GovernanceError("Git origin must define fetch and push URLs")
        remotes.extend(values)
    identities = {_normalize_remote(remote).lower(): remote for remote in remotes}
    if len(identities) != 1:
        raise GovernanceError(
            "Every origin fetch and push URL must identify the same GitHub repository"
        )
    return _normalize_remote(next(iter(identities.values())))


def _validate_git_repository(root: Path) -> tuple[Path, str]:
    """Require a real exact worktree root and return its verified origin identity."""

    try:
        metadata = root.lstat()
    except OSError as exc:
        raise GovernanceError(f"Repository root is unavailable: {root}") from exc
    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISDIR(metadata.st_mode):
        raise GovernanceError(f"Repository root must be a real directory: {root}")
    resolved = root.resolve()
    top_level = Path(_run_git(resolved, ("rev-parse", "--show-toplevel")).strip()).resolve()
    if top_level != resolved:
        raise GovernanceError(
            f"Repository root must be the exact Git worktree root: {resolved} != {top_level}"
        )
    return resolved, _remote_identity(resolved)


def _safe_local_file(root: Path, relative_path: str) -> Path:
    resolved_root = root.resolve()
    safe_relative = _relative_path(relative_path, "local artifact path")
    parts = PurePosixPath(safe_relative).parts
    candidate = resolved_root / safe_relative
    current = resolved_root
    for index, part in enumerate(parts):
        current = current / part
        if not current.exists() and not current.is_symlink():
            continue
        metadata = current.lstat()
        if stat.S_ISLNK(metadata.st_mode):
            raise GovernanceError(f"Local artifact path traverses a symlink: {current}")
        if index < len(parts) - 1 and not stat.S_ISDIR(metadata.st_mode):
            raise GovernanceError(
                f"Local artifact parent is not a directory: {current}"
            )
    try:
        candidate.resolve(strict=False).relative_to(resolved_root)
    except (OSError, ValueError) as exc:
        raise GovernanceError(
            f"Local artifact path escapes repository root: {relative_path}"
        ) from exc
    return candidate


def check_repository(
    root: Path,
    repository: str | None = None,
    *,
    fetch: Callable[[str], bytes] | None = None,
) -> tuple[int, tuple[str, ...]]:
    """Return ``(checked_count, problems)`` without modifying the repository."""

    root, actual_identity = _validate_git_repository(root)
    pin = read_pin(root)
    fetcher = fetch or fetch_url
    manifest_bytes = fetcher(raw_url(pin, CANONICAL_MANIFEST_PATH))
    manifest = parse_manifest(manifest_bytes)
    consumer = manifest.consumer_for(actual_identity)
    asserted_identity = repository or os.environ.get("GITHUB_REPOSITORY")
    if asserted_identity is not None:
        asserted_consumer = manifest.consumer_for(asserted_identity)
        if asserted_consumer.key != consumer.key:
            raise GovernanceError(
                f"Asserted repository {asserted_identity!r} disagrees with "
                f"origin {actual_identity!r}"
            )
    if manifest.pin_path != DEFAULT_PIN_PATH:
        raise GovernanceError(
            f"Canonical manifest pin path is {manifest.pin_path!r}; checker expects "
            f"{DEFAULT_PIN_PATH!r}"
        )

    checked = 0
    problems: list[str] = []
    for artifact in manifest.artifacts_for(consumer):
        canonical = fetcher(raw_url(pin, artifact.source))
        digest = hashlib.sha256(canonical).hexdigest()
        if digest != artifact.sha256:
            problems.append(
                f"CANONICAL ERROR: {artifact.source} checksum differs from manifest"
            )
            continue
        target = expand_target(artifact, consumer)
        try:
            local_path = _safe_local_file(root, target)
        except GovernanceError as exc:
            problems.append(f"UNSAFE: {target}: {exc}")
            continue
        if not local_path.is_file():
            problems.append(f"MISSING: {target}")
            continue
        try:
            local = local_path.read_bytes()
            local_mode = local_path.stat().st_mode
            executable = bool(local_mode & stat.S_IXUSR)
        except OSError as exc:
            problems.append(f"ERROR: cannot read {target}: {exc}")
            continue
        if local != canonical:
            problems.append(
                f"DRIFT: {target} differs from {CANONICAL_REPOSITORY}@{pin[:8]}"
            )
        expected_executable = bool(artifact.mode & stat.S_IXUSR)
        if executable != expected_executable:
            expected = "executable" if expected_executable else "non-executable"
            problems.append(f"MODE: {target} must be {expected}")
        if local_mode & (stat.S_IWGRP | stat.S_IWOTH):
            problems.append(f"MODE: {target} must not be group/other-writable")
        checked += 1
    return checked, tuple(problems)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Check vendored Mech artifacts against an immutable claw commit"
    )
    parser.add_argument("--root", type=Path, default=Path.cwd())
    parser.add_argument(
        "--repository",
        help="Mech key or exact owner/repository identity (normally auto-detected)",
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        checked, problems = check_repository(args.root, args.repository)
    except CanonicalFetchError as exc:
        print(f"FETCH ERROR: {exc}", file=sys.stderr)
        return 1
    except GovernanceError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2
    for problem in problems:
        print(problem, file=sys.stderr)
    if problems:
        print(
            f"Vendored drift detected ({len(problems)} problem(s), {checked} checked).",
            file=sys.stderr,
        )
        return 1
    print(f"OK: {checked} governed artifacts match the pinned claw revision")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Fleet contract for native Codex research and provider canaries.

``culturebotai-claw`` is the canonical copy. Mechs vendor this file
byte-for-byte and pin the immutable claw revision that supplied it.

The Codex lane deliberately does not route through deep-research-client's
``cyberian`` adapter. It invokes ``codex --search exec`` directly, requires a
JSON-schema response, validates the response locally, and only then publishes
the markdown report with an atomic rename.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import shlex
import shutil
import subprocess
import tempfile
from collections.abc import Callable, Mapping, Sequence
from dataclasses import dataclass
from pathlib import Path
from typing import Any
from urllib.parse import urlsplit, urlunsplit

DEFAULT_MIN_CHARS = 1_000
DEFAULT_MIN_SOURCES = 3
DEFAULT_TIMEOUT = 1_800
OPENSCIENTIST_KEY = "OPENSCIENTIST_API_KEY"
OPENSCIENTIST_URL = "OPENSCIENTIST_URL"
_URL = re.compile(r"https?://[^\s)\]>,]+", re.IGNORECASE)
_PLACEHOLDER = re.compile(r"\{([a-z][a-z0-9_]*)\}")


class ContractError(RuntimeError):
    """A provider or output failed the fleet research contract."""


@dataclass(frozen=True)
class ValidationSummary:
    characters: int
    sources: int


@dataclass(frozen=True)
class CanaryResult:
    provider: str
    ok: bool
    detail: str


def _canonical_url(value: str) -> str:
    value = value.strip().rstrip(".,;:")
    parsed = urlsplit(value)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise ContractError(f"invalid source URL: {value!r}")
    return urlunsplit(
        (
            parsed.scheme.casefold(),
            parsed.netloc.casefold(),
            parsed.path,
            parsed.query,
            "",
        )
    )


def codex_output_schema(min_sources: int = DEFAULT_MIN_SOURCES) -> dict[str, Any]:
    """Schema passed to ``codex exec --output-schema`` and rechecked locally."""
    if min_sources < 1:
        raise ValueError("min_sources must be at least 1")
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "type": "object",
        "additionalProperties": False,
        "required": ["report_markdown", "sources", "limitations"],
        "properties": {
            "report_markdown": {"type": "string"},
            "sources": {
                "type": "array",
                "minItems": min_sources,
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["title", "url"],
                    "properties": {
                        "title": {"type": "string"},
                        "url": {"type": "string"},
                    },
                },
            },
            "limitations": {"type": "array", "items": {"type": "string"}},
        },
    }


def render_prompt_template(template: Path, variables: Mapping[str, str]) -> str:
    """Fill a Mech prompt and refuse to send unresolved named placeholders."""
    body = template.read_text(encoding="utf-8")
    for key, value in variables.items():
        body = body.replace("{" + key + "}", str(value))
    missing = sorted(set(_PLACEHOLDER.findall(body)))
    if missing:
        raise ContractError(f"unfilled research template placeholders: {missing}")
    return body


def build_codex_command(
    *,
    repo_root: Path,
    schema_path: Path,
    response_path: Path,
    executable: str = "codex",
) -> list[str]:
    """Build the canonical non-interactive, web-enabled, read-only command."""
    return [
        executable,
        "--search",
        "--ask-for-approval",
        "never",
        "exec",
        "--ephemeral",
        "--sandbox",
        "read-only",
        "--cd",
        str(repo_root),
        "--output-schema",
        str(schema_path),
        "--output-last-message",
        str(response_path),
        "-",
    ]


def validate_codex_payload(
    payload: Any,
    *,
    min_chars: int = DEFAULT_MIN_CHARS,
    min_sources: int = DEFAULT_MIN_SOURCES,
) -> ValidationSummary:
    """Apply semantic checks JSON Schema alone cannot express."""
    if not isinstance(payload, dict):
        raise ContractError("Codex response must be a JSON object")
    if set(payload) != {"report_markdown", "sources", "limitations"}:
        raise ContractError("Codex response has missing or unexpected top-level fields")

    report = payload["report_markdown"]
    if not isinstance(report, str) or len(report.strip()) < min_chars:
        actual = len(report.strip()) if isinstance(report, str) else 0
        raise ContractError(
            f"research report is too short: {actual} characters; require {min_chars}"
        )
    limitations = payload["limitations"]
    if not isinstance(limitations, list) or not all(
        isinstance(item, str) and item.strip() for item in limitations
    ):
        raise ContractError("limitations must be a list of non-empty strings")

    sources = payload["sources"]
    if not isinstance(sources, list):
        raise ContractError("sources must be a list")
    urls: set[str] = set()
    for source in sources:
        if not isinstance(source, dict) or set(source) != {"title", "url"}:
            raise ContractError("each source must contain exactly title and url")
        if not isinstance(source["title"], str) or not source["title"].strip():
            raise ContractError("each source title must be non-empty")
        if not isinstance(source["url"], str):
            raise ContractError("each source URL must be a string")
        urls.add(_canonical_url(source["url"]))
    if len(urls) < min_sources:
        raise ContractError(
            f"research report has {len(urls)} distinct sources; require {min_sources}"
        )
    return ValidationSummary(characters=len(report.strip()), sources=len(urls))


def render_codex_payload(payload: Mapping[str, Any]) -> str:
    """Render validated structured output as the fleet's markdown artifact."""
    lines = [str(payload["report_markdown"]).strip(), "", "## Sources", ""]
    for source in payload["sources"]:
        lines.append(f"- [{source['title']}]({source['url']})")
    if payload["limitations"]:
        lines.extend(["", "## Limitations", ""])
        lines.extend(f"- {item}" for item in payload["limitations"])
    return "\n".join(lines).rstrip() + "\n"


def run_codex_research(
    prompt: str,
    destination: Path,
    *,
    repo_root: Path,
    timeout: int = DEFAULT_TIMEOUT,
    min_chars: int = DEFAULT_MIN_CHARS,
    min_sources: int = DEFAULT_MIN_SOURCES,
    executable: str = "codex",
    runner: Callable[..., subprocess.CompletedProcess[str]] = subprocess.run,
) -> ValidationSummary:
    """Run Codex and atomically publish a report only after full validation."""
    if not prompt.strip():
        raise ContractError("research prompt must not be empty")
    destination.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="codex-research-") as temp_dir:
        temp = Path(temp_dir)
        schema_path = temp / "output.schema.json"
        response_path = temp / "response.json"
        schema_path.write_text(
            json.dumps(codex_output_schema(min_sources), indent=2) + "\n",
            encoding="utf-8",
        )
        command = build_codex_command(
            repo_root=repo_root,
            schema_path=schema_path,
            response_path=response_path,
            executable=executable,
        )
        try:
            completed = runner(
                command,
                input=prompt,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            raise ContractError(f"codex exec timed out after {timeout} seconds") from exc
        if completed.returncode:
            detail = (completed.stderr or completed.stdout or "").strip()[-800:]
            raise ContractError(f"codex exec failed with exit {completed.returncode}: {detail}")
        if not response_path.is_file():
            raise ContractError("codex exec succeeded without writing its structured response")
        try:
            payload = json.loads(response_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as exc:
            raise ContractError("codex exec returned invalid JSON") from exc
        summary = validate_codex_payload(payload, min_chars=min_chars, min_sources=min_sources)
        rendered = render_codex_payload(payload)
        publish_path = destination.with_name(f".{destination.name}.tmp")
        publish_path.write_text(rendered, encoding="utf-8")
        os.replace(publish_path, destination)
        return summary


def validate_openscientist_credential(environ: Mapping[str, str]) -> str:
    """Validate documented ``name:secret`` shape without returning the secret."""
    raw = environ.get(OPENSCIENTIST_KEY, "")
    if not raw:
        raise ContractError(f"set {OPENSCIENTIST_KEY}=name:secret")
    name, separator, secret = raw.partition(":")
    if not separator or not name.strip() or not secret.strip():
        raise ContractError(f"{OPENSCIENTIST_KEY} must use the name:secret format")
    return name.strip()


def codex_canary(
    *,
    executable: str = "codex",
    runner: Callable[..., subprocess.CompletedProcess[str]] = subprocess.run,
) -> CanaryResult:
    """Check CLI capabilities and authentication without starting research."""
    if shutil.which(executable) is None and executable == "codex":
        return CanaryResult("codex", False, "codex executable not found on PATH")
    checks: Sequence[tuple[list[str], tuple[str, ...]]] = (
        ([executable, "--help"], ("--search",)),
        ([executable, "exec", "--help"], ("--output-schema", "--output-last-message")),
        ([executable, "login", "status"], ("Logged in",)),
    )
    for command, required in checks:
        try:
            completed = runner(command, capture_output=True, text=True, timeout=20, check=False)
        except (OSError, subprocess.TimeoutExpired) as exc:
            return CanaryResult("codex", False, f"could not run {' '.join(command[:2])}: {exc}")
        output = (completed.stdout or "") + (completed.stderr or "")
        if completed.returncode or any(token not in output for token in required):
            return CanaryResult(
                "codex", False, f"{' '.join(command[:2])} failed the capability check"
            )
    return CanaryResult("codex", True, "CLI authenticated; web search and schema output supported")


def openscientist_canary(
    *,
    environ: Mapping[str, str] | None = None,
    client_command: str = "deep-research-client",
    runner: Callable[..., subprocess.CompletedProcess[str]] = subprocess.run,
) -> CanaryResult:
    """Check credential shape and client discovery without submitting a paid job."""
    env = os.environ if environ is None else environ
    try:
        validate_openscientist_credential(env)
    except ContractError as exc:
        return CanaryResult("openscientist", False, str(exc))
    try:
        completed = runner(
            [*shlex.split(client_command), "providers"],
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
            env=dict(env),
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return CanaryResult("openscientist", False, f"provider discovery failed: {exc}")
    output = (completed.stdout or "") + (completed.stderr or "")
    if completed.returncode or "openscientist" not in output.casefold():
        return CanaryResult(
            "openscientist", False, "deep-research-client did not list openscientist"
        )
    return CanaryResult(
        "openscientist",
        True,
        "credential shape valid and provider discovered; no job submitted",
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("provider", choices=("codex", "openscientist", "all"))
    parser.add_argument("--codex-command", default="codex")
    parser.add_argument("--client-command", default="deep-research-client")
    args = parser.parse_args(argv)
    results: list[CanaryResult] = []
    if args.provider in {"codex", "all"}:
        results.append(codex_canary(executable=args.codex_command))
    if args.provider in {"openscientist", "all"}:
        results.append(openscientist_canary(client_command=args.client_command))
    for result in results:
        label = "OK" if result.ok else "BLOCKED"
        print(f"{label}: {result.provider}: {result.detail}")
    return 0 if all(result.ok for result in results) else 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Fill mechanically eligible empty chemistry blocks from exact ChEBI OLS terms.

Existing chemistry, mapping grades, ingredient types and identities are preserved.
No automatic cache/PubChem fallback or partial-block gap filling is permitted.
"""

from __future__ import annotations

import sys
from pathlib import Path

import click
import yaml
from rich.console import Console

_project_root = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(_project_root / "src"))

from mediaingredientmech.curate.curation_event import record_curation_event  # noqa: E402
from mediaingredientmech.curation.chemical_properties_guard import (  # noqa: E402
    chemistry_preflight,
    prepare_chemical_properties,
)
from mediaingredientmech.utils.yaml_handler import save_yaml  # noqa: E402
from mediaingredientmech.validation.write_validated import ValidationFailedError  # noqa: E402

console = Console()


def load_ingredients(yaml_path: Path) -> dict:
    """Load the collection without discarding its metadata."""
    with open(yaml_path) as stream:
        return yaml.safe_load(stream)


def filter_chebi_without_properties(data: dict | list) -> list[dict]:
    """Pure scope filter; grades do not grant or prohibit eligibility.

    All nonempty blocks, including CAS-only or provenance-only blocks, require
    explicit curation rather than adding fields under their existing provenance.
    """
    records = data.get("ingredients", []) if isinstance(data, dict) else data
    return [
        record
        for record in records
        if record.get("chemical_properties") in (None, {}) and chemistry_preflight(record) is None
    ]


@click.command()
@click.option(
    "--input",
    "-i",
    "input_path",
    type=click.Path(exists=True, path_type=Path),
    default=Path("data/curated/mapped_ingredients.yaml"),
)
@click.option("--output", "-o", "output_path", type=click.Path(path_type=Path), default=None)
@click.option("--dry-run", is_flag=True, help="Inspect the same guarded proposals without writing")
@click.option("--limit", type=int, default=None)
def main(input_path: Path, output_path: Path | None, dry_run: bool, limit: int | None):
    """Propose exact OLS chemistry only for explicitly eligible empty blocks."""
    data = load_ingredients(input_path)
    records = filter_chebi_without_properties(data)
    if limit is not None:
        records = records[:limit]
    enriched = skipped = failed = 0
    for record in records:
        proposal, explanation = prepare_chemical_properties(record)
        if proposal:
            enriched += 1
            console.print(
                f"{'Would enrich' if dry_run else 'Enriched'} {record.get('preferred_term')}: {explanation}"
            )
            if not dry_run:
                record["chemical_properties"] = proposal
                record_curation_event(
                    record,
                    curator="enrich_chemical_properties.py",
                    action="AUTO_BACKFILL_CHEBI_CHEMISTRY",
                    changes=explanation,
                )
        elif explanation == "PROVIDER_FAILURE":
            failed += 1
            console.print(f"Provider failure: {record.get('preferred_term')}")
        else:
            skipped += 1
            console.print(f"Skipped {record.get('preferred_term')}: {explanation}")
    console.print(f"Enriched: {enriched}; Skipped: {skipped}; Failed: {failed}")
    if enriched and not dry_run:
        try:
            save_yaml(
                data, output_path or input_path, validate=True, target_class="IngredientCollection"
            )
        except ValidationFailedError as exc:
            print(exc.summary(), file=sys.stderr)
            raise
    if failed:
        raise click.ClickException(f"{failed} chemical property provider failures")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Re-ground the unblocked exact-hydrate residuals from #321.

The repaired hydrate-grounding report (#461) left a small cohort whose preferred
terms name a hydrate while their published rows still point at an anhydrous
parent. The #321 ChEBI triage identified six that looked immediately fixable
because ChEBI now has a term whose label is exactly the parent label plus
"hydrate".

Two are no longer work for this script:

* `MgCl2x 6 H2O` has already merged into `MgCl2 x 6 H2O`.
* `Citric Acid*H2O` has a specific target, but its current `CHEBI:30769`
  identifier is shared with live anhydrous `Citric acid`, so the occurrence and
  membership rows cannot be moved without splitting duplicate evidence first.
* `Fe2(SO4)3 x n H2O` needs a variable-hydrate identity: ChEBI's
  "iron(3+) sulfate hydrate" term is the monohydrate by formula and exact
  synonym, while this label denotes variable hydration.

That leaves two promotions to exact ChEBI hydrate terms, plus one local
solution whose own identity stays `kgmicrobe.ingredient:` but whose parent
`closeMatch` moves from the anhydrous hydrochloride to the monohydrate.

    python scripts/fix_remaining_hydrate_regroundings.py
    python scripts/fix_remaining_hydrate_regroundings.py --apply
"""

from __future__ import annotations

import argparse
import re
import sqlite3
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src"))
import yaml  # noqa: E402

from mediaingredientmech.utils.oaklib_cache import db_path  # noqa: E402
from mediaingredientmech.sssom_grading import (  # noqa: E402
    CONFIDENCE,
    JUSTIFICATION,
    PREDICATE,
)
from mediaingredientmech.synonym_policy import is_resolving_synonym  # noqa: E402
from mediaingredientmech.utils.object_source import object_source_for  # noqa: E402
from mediaingredientmech.utils.yaml_handler import save_yaml  # noqa: E402

COLLECTION = ROOT / "data" / "curated" / "mapped_ingredients.yaml"
SSSOM = ROOT / "mappings" / "ingredient_mappings.sssom.tsv"
MEMBERSHIP = ROOT / "mappings" / "culturemech_recipe_membership.tsv"
CHEBI_DB = db_path("CHEBI")

STAMP = "2026-09-10T00:00:00+00:00"
CURATOR = "fix_remaining_hydrate_regroundings"
ISSUE = "#321"

PROMOTE = {
    "Esculin Monohydrate": {
        "old_identifier": "CHEBI:4853",
        "old_parent": "CHEBI:4853",
        "new_identifier": "CHEBI:73111",
        "new_label": "esculin hydrate",
    },
    "Betaine x H2O": {
        "old_identifier": "kgmicrobe.compound:betaine_x_h2o",
        "old_parent": "CHEBI:17750",
        "new_identifier": "CHEBI:91242",
        "new_label": "glycine betaine hydrate",
    },
}

LOCAL_PARENT = {
    "L-Cysteine x HCl x H2O solution": {
        "identifier": "kgmicrobe.ingredient:l-cysteine_x_hcl_x_h2o_solution",
        "old_parent": "CHEBI:91247",
        "new_parent": "CHEBI:91248",
        "new_label": "L-cysteine hydrochloride hydrate",
    },
}

COMPONENT_RESCOPES = {
    "Esculin Ferric Citrate": {
        "component_name": "esculin",
        "component_id": "CHEBI:4853",
        "old_scope": "MIM_CATALOG",
        "new_scope": "EXTERNAL_TERM",
    },
}

MEMBERSHIP_REWRITES = {
    "kgmicrobe.compound:betaine_x_h2o": ("CHEBI:91242", "Betaine x H2O"),
}

FORMULA = "chemrof:generalized_empirical_formula"
INCHI = "chemrof:inchi_string"
SMILES = "chemrof:smiles_string"
CAS = re.compile(r"^cas:(\d{2,7}-\d{2}-\d)$")
HYDRATE_SYNONYM_SOURCE = "chebi_synonym_review"
MAX_OTHER_ENTRIES = 50


def find(records: list[dict], *, label: str) -> dict:
    hits = [
        rec for rec in records
        if rec.get("preferred_term") == label and rec.get("mapping_status") == "MAPPED"
    ]
    if len(hits) != 1:
        raise SystemExit(f"expected one active record named {label!r}; found {len(hits)}")
    return hits[0]


def chebi_props(conn: sqlite3.Connection, curie: str) -> dict[str, str]:
    rows = conn.execute(
        "SELECT predicate, value FROM statements WHERE subject=?",
        (curie,),
    ).fetchall()
    by_pred: dict[str, str] = {}
    cas_values: list[str] = []
    for predicate, value in rows:
        if predicate in {FORMULA, INCHI, SMILES}:
            by_pred[predicate] = value
        if predicate == "oio:hasDbXref":
            match = CAS.match(value)
            if match:
                cas_values.append(match.group(1))

    for predicate in (FORMULA, INCHI, SMILES):
        if predicate not in by_pred:
            raise SystemExit(f"{curie} has no {predicate} in {CHEBI_DB}")

    out = {
        "molecular_formula": by_pred[FORMULA],
        "inchi": by_pred[INCHI],
        "smiles": by_pred[SMILES],
    }
    if len(cas_values) > 1:
        raise SystemExit(f"{curie} has multiple CAS xrefs: {cas_values}")
    if cas_values:
        out["cas_rn"] = cas_values[0]
    return out


def chebi_exact_synonyms(conn: sqlite3.Connection, curie: str) -> list[str]:
    return sorted({
        str(row[0])
        for row in conn.execute(
            "SELECT value FROM statements "
            "WHERE subject=? AND predicate='oio:hasExactSynonym' "
            "AND value IS NOT NULL",
            (curie,),
        )
    })


def exact_hydrate_chemical_properties(
    current: dict,
    props: dict[str, str],
    curie: str,
) -> dict:
    updated = {
        **current,
        **props,
        "data_source": f"OAK/CHEBI exact hydrate term {curie}",
        "retrieval_date": STAMP,
    }
    if not props.get("cas_rn"):
        updated.pop("cas_rn", None)
    return updated


def hydrate_exact_synonyms(conn: sqlite3.Connection, new_id: str) -> list[dict]:
    return [
        {
            "synonym_text": text,
            "synonym_type": "EXACT_SYNONYM",
            "source": HYDRATE_SYNONYM_SOURCE,
        }
        for text in chebi_exact_synonyms(conn, new_id)
    ]


def replace_exact_synonyms(record: dict, replacements: list[dict]) -> int:
    replacements_by_text = {
        str(synonym["synonym_text"]).casefold(): synonym
        for synonym in replacements
    }
    replacement_texts = set(replacements_by_text)
    kept = []
    removed = 0
    for synonym in record.get("synonyms") or []:
        synonym_type = synonym.get("synonym_type")
        source = synonym.get("source")
        text = str(synonym.get("synonym_text") or "")
        if (
            synonym_type == "EXACT_SYNONYM"
            and source in {
                "kg_microbe",
                "merged_from_duplicate_mim_record",
                HYDRATE_SYNONYM_SOURCE,
            }
            and text.casefold() not in replacement_texts
        ):
            removed += 1
            continue
        kept.append(synonym)

    existing = {
        str(synonym.get("synonym_text") or "").casefold()
        for synonym in kept
    }
    for folded, synonym in replacements_by_text.items():
        if folded not in existing:
            kept.append(synonym)
            existing.add(folded)

    record["synonyms"] = kept
    return removed


def append_mapping_source(source: str, token: str = f"MIM:MIM curation ({ISSUE})") -> str:
    tokens = [part for part in source.split("|") if part]
    if token not in tokens:
        tokens.append(token)
    return "|".join(tokens)


def _set(fields: list[str], column: dict[str, int], name: str, value: str) -> None:
    fields[column[name]] = value


def _sync_grade(fields: list[str], column: dict[str, int], quality: str) -> None:
    _set(fields, column, "predicate_id", PREDICATE[quality])
    _set(fields, column, "mapping_justification", JUSTIFICATION[quality])
    _set(fields, column, "confidence", CONFIDENCE[quality])


def _sssom_other(record: dict, *, object_label: str, cas: str = "") -> str:
    drop = {
        str(record.get("preferred_term") or "").strip().casefold(),
        object_label.strip().casefold(),
        "",
    }
    out: list[str] = []
    seen: set[str] = set()
    for synonym in record.get("synonyms") or []:
        if not isinstance(synonym, dict) or not is_resolving_synonym(synonym):
            continue
        token = str(synonym.get("synonym_text") or "").strip()
        key = token.casefold()
        if key in drop or key in seen:
            continue
        seen.add(key)
        out.append(token)
        if len(out) >= MAX_OTHER_ENTRIES:
            break

    cas_token = f"CAS:{cas}" if cas else ""
    cas_key = cas_token.casefold()
    if cas_token and cas_key not in drop and cas_key not in seen:
        out.append(cas_token)
    return "|".join(out)


def sssom_other_by_label(records: list[dict], cas_by_label: dict[str, str]) -> dict[str, str]:
    labels = set(PROMOTE) | set(LOCAL_PARENT)
    return {
        str(record["preferred_term"]): _sssom_other(
            record,
            object_label=str((record.get("ontology_mapping") or {}).get("ontology_label") or ""),
            cas=cas_by_label.get(str(record["preferred_term"]), ""),
        )
        for record in records
        if record.get("preferred_term") in labels
    }


def rewrite_sssom(other_by_label: dict[str, str]) -> tuple[str, int, int]:
    lines = SSSOM.read_text(encoding="utf-8").splitlines(keepends=True)
    header = next(i for i, line in enumerate(lines) if line.startswith("subject_id"))
    columns = lines[header].rstrip("\n").split("\t")
    column = {name: index for index, name in enumerate(columns)}
    updated = 0
    dropped = 0
    seen_promotions: set[str] = set()
    seen_local_parents: set[str] = set()
    seen_local_registry: set[str] = set()
    out: list[str] = []

    for line in lines:
        cells = line.rstrip("\n").split("\t")
        eol = "\n" if line.endswith("\n") else ""
        if len(cells) < len(columns) or cells[0].startswith("#") or cells[0] == "subject_id":
            out.append(line)
            continue

        label = cells[column["subject_label"]]
        object_id = cells[column["object_id"]]
        if label in PROMOTE:
            spec = PROMOTE[label]
            if object_id == spec["old_identifier"] and object_id != spec["old_parent"]:
                dropped += 1
                continue
            if object_id == spec["old_parent"]:
                _set(cells, column, "object_id", spec["new_identifier"])
                _set(cells, column, "object_label", spec["new_label"])
                _set(cells, column, "object_source", object_source_for(spec["new_identifier"]))
                _sync_grade(cells, column, "EXACT_MATCH")
                _set(
                    cells,
                    column,
                    "source",
                    append_mapping_source(cells[column["source"]]),
                )
                _set(cells, column, "comment", "")
                _set(cells, column, "mapping_date", STAMP[:10])
                _set(cells, column, "other", other_by_label[label])
                _set(cells, column, "validation_method", "")
                updated += 1
                seen_promotions.add(label)
        elif label in LOCAL_PARENT:
            spec = LOCAL_PARENT[label]
            if object_id == spec["old_parent"]:
                _set(cells, column, "object_id", spec["new_parent"])
                _set(cells, column, "object_label", spec["new_label"])
                _set(cells, column, "object_source", object_source_for(spec["new_parent"]))
                _sync_grade(cells, column, "CLOSE_MATCH")
                _set(
                    cells,
                    column,
                    "source",
                    append_mapping_source(cells[column["source"]]),
                )
                _set(cells, column, "mapping_date", STAMP[:10])
                _set(cells, column, "other", other_by_label[label])
                _set(cells, column, "validation_method", "")
                updated += 1
                seen_local_parents.add(label)
            elif object_id == spec["identifier"]:
                cells[column["comment"]] = (
                    f"Registry/identity row preserving {spec['identifier']} "
                    f"alongside parent {spec['new_parent']}."
                )
                _set(cells, column, "mapping_date", STAMP[:10])
                updated += 1
                seen_local_registry.add(label)
        out.append("\t".join(cells) + eol)

    missed = sorted(set(PROMOTE) - seen_promotions)
    if missed:
        raise SystemExit(f"failed to update promoted SSSOM row(s): {missed}")
    missed = sorted(set(LOCAL_PARENT) - seen_local_parents)
    if missed:
        raise SystemExit(f"failed to update local parent SSSOM row(s): {missed}")
    missed = sorted(set(LOCAL_PARENT) - seen_local_registry)
    if missed:
        raise SystemExit(f"failed to update local registry SSSOM row(s): {missed}")
    if dropped != 1:
        raise SystemExit(f"expected to drop one withdrawn registry row, dropped {dropped}")
    if out and not out[-1].endswith("\n"):
        out[-1] += "\n"
    return "".join(out), updated, dropped


def rewrite_membership(replacements: dict[str, str]) -> tuple[str, dict[str, int]]:
    lines = MEMBERSHIP.read_text(encoding="utf-8").splitlines(keepends=True)
    comments: list[str] = []
    table: list[list[str]] = []
    moved = dict.fromkeys(replacements, 0)

    for line in lines:
        if line.startswith("#"):
            comments.append(line if line.endswith("\n") else f"{line}\n")
            continue
        fields = line.rstrip("\n").split("\t")
        if fields[0] in replacements:
            old = fields[0]
            fields[0] = replacements[old]
            moved[old] += 1
        table.append(fields)

    header, rows = table[0], table[1:]
    rows.sort(key=lambda row: tuple(row[:2]))
    keys = [(row[0], row[1]) for row in rows]
    if len(keys) != len(set(keys)):
        raise SystemExit("membership rewrite would create duplicate edge keys")

    out = [*comments, "\t".join(header) + "\n"]
    out.extend("\t".join(row) + "\n" for row in rows)
    return "".join(out), moved


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--chebi-db", type=Path, default=CHEBI_DB)
    args = ap.parse_args(argv)

    if not args.chebi_db.exists():
        raise SystemExit(f"ChEBI SQLite not found at {args.chebi_db}")

    conn = sqlite3.connect(f"file:{args.chebi_db}?mode=ro", uri=True)
    doc = yaml.safe_load(COLLECTION.read_text(encoding="utf-8")) or {}
    records = doc.get("ingredients") or []
    active = {
        str(rec.get("identifier") or "")
        for rec in records
        if rec.get("mapping_status") != "REJECTED"
    }
    actions: list[str] = []
    cas_by_label: dict[str, str] = {}

    for label, spec in PROMOTE.items():
        rec = find(records, label=label)
        old_identifier = spec["old_identifier"]
        if rec.get("identifier") != old_identifier:
            raise SystemExit(f"{label} is on {rec.get('identifier')}, not {old_identifier}")
        if spec["new_identifier"] in active:
            raise SystemExit(f"{spec['new_identifier']} is already held by an active record")

        props = chebi_props(conn, spec["new_identifier"])
        cas = props.get("cas_rn") or ""
        cas_by_label[label] = cas

        rec["identifier"] = spec["new_identifier"]
        if rec.get("kg_microbe_node_id") in {old_identifier, spec["old_parent"]}:
            rec["kg_microbe_node_id"] = spec["new_identifier"]
        om = rec.setdefault("ontology_mapping", {})
        old_parent = om.get("ontology_id")
        old_label = om.get("ontology_label")
        om.update({
            "ontology_id": spec["new_identifier"],
            "ontology_label": spec["new_label"],
            "ontology_source": "CHEBI",
            "mapping_quality": "EXACT_MATCH",
        })
        om.setdefault("evidence", []).append({
            "evidence_type": "DATABASE_MATCH",
            "source": f"MIM curation ({ISSUE})",
            "notes": (
                f"Promoted from {old_parent} ({old_label!r}) to the exact ChEBI "
                f"hydrate term {spec['new_identifier']} ({spec['new_label']!r}). "
                "The label names a hydrate and ChEBI has a term for that hydrate, "
                "so MAPPING_SEMANTICS.md Section 3 step 1 applies."
            ),
        })
        rec["chemical_properties"] = exact_hydrate_chemical_properties(
            rec.get("chemical_properties") or {},
            props,
            spec["new_identifier"],
        )
        synonym_replacements = hydrate_exact_synonyms(
            conn, spec["new_identifier"]
        )
        removed_synonyms = replace_exact_synonyms(rec, synonym_replacements)
        rec.setdefault("curation_history", []).append({
            "timestamp": STAMP,
            "curator": CURATOR,
            "action": "PROMOTED_TO_SPECIFIC_HYDRATE",
            "changes": (
                f"identifier {old_identifier} -> {spec['new_identifier']}; "
                f"ontology_id {old_parent} -> {spec['new_identifier']}; "
                f"mapping_quality -> EXACT_MATCH. Structure fields were copied "
                f"from the exact ChEBI hydrate term, {removed_synonyms} stale "
                "anhydrous exact synonym(s) were replaced, and stale "
                f"kg_microbe_node_id values were aligned where present ({ISSUE})."
            ),
            "llm_assisted": False,
        })
        actions.append(f"PROMOTE {label}: {old_identifier} -> {spec['new_identifier']}")

    for label, spec in LOCAL_PARENT.items():
        rec = find(records, label=label)
        if rec.get("identifier") != spec["identifier"]:
            raise SystemExit(f"{label} is on {rec.get('identifier')}, not {spec['identifier']}")
        om = rec.setdefault("ontology_mapping", {})
        if om.get("ontology_id") != spec["old_parent"]:
            raise SystemExit(f"{label} parent is {om.get('ontology_id')}, not {spec['old_parent']}")
        om.update({
            "ontology_id": spec["new_parent"],
            "ontology_label": spec["new_label"],
            "ontology_source": "CHEBI",
            "mapping_quality": "CLOSE_MATCH",
        })
        om.setdefault("evidence", []).append({
            "evidence_type": "DATABASE_MATCH",
            "source": f"MIM curation ({ISSUE})",
            "notes": (
                f"Repointed the local solution identity's parent from "
                f"{spec['old_parent']} to the hydrate-specific {spec['new_parent']} "
                f"({spec['new_label']!r}). The record still denotes a prepared "
                "solution, not the pure ChEBI compound, so it keeps its "
                "kgmicrobe.ingredient identifier and closeMatch grade."
            ),
        })
        rec.setdefault("curation_history", []).append({
            "timestamp": STAMP,
            "curator": CURATOR,
            "action": "CORRECTED_PARENT",
            "changes": (
                f"ontology_id {spec['old_parent']} -> {spec['new_parent']} while "
                f"retaining local identifier {spec['identifier']} ({ISSUE})."
            ),
            "llm_assisted": False,
        })
        actions.append(f"PARENT  {label}: {spec['old_parent']} -> {spec['new_parent']}")

    for label, spec in COMPONENT_RESCOPES.items():
        rec = find(records, label=label)
        components = [
            component for component in rec.get("components") or []
            if component.get("component_name") == spec["component_name"]
            and component.get("component_id") == spec["component_id"]
        ]
        if len(components) != 1:
            raise SystemExit(
                f"expected one {label} component on {spec['component_id']}; "
                f"found {len(components)}"
            )
        component = components[0]
        if component.get("reference_scope") != spec["old_scope"]:
            raise SystemExit(
                f"{label} {spec['component_name']} scope is "
                f"{component.get('reference_scope')}, not {spec['old_scope']}"
            )
        component["reference_scope"] = spec["new_scope"]
        rec.setdefault("curation_history", []).append({
            "timestamp": STAMP,
            "curator": CURATOR,
            "action": "RESCOPED_COMPONENT",
            "changes": (
                f"{spec['component_name']} component reference_scope "
                f"{spec['old_scope']} -> {spec['new_scope']}. "
                f"{spec['component_id']} names anhydrous esculin; after "
                f"Esculin Monohydrate moved to CHEBI:73111, no active MIM "
                f"record represents that component ({ISSUE})."
            ),
            "llm_assisted": False,
        })
        actions.append(
            f"COMPONENT {label}: {spec['component_id']} {spec['old_scope']} "
            f"-> {spec['new_scope']}"
        )

    sssom_text, sssom_updated, sssom_dropped = rewrite_sssom(
        sssom_other_by_label(records, cas_by_label)
    )
    membership_replacements = {
        old: new for old, (new, _label) in MEMBERSHIP_REWRITES.items()
    }
    membership_text, moved_edges = rewrite_membership(membership_replacements)
    for old, (_new, label) in MEMBERSHIP_REWRITES.items():
        stats = find(records, label=label).get("occurrence_statistics") or {}
        if moved_edges[old] != stats.get("media_count"):
            raise SystemExit(
                f"moved {moved_edges[old]} {label} membership edge(s), but "
                f"media_count is {stats.get('media_count')}"
            )

    print(f"{len(actions)} curation action(s)")
    for action in actions:
        print(f"  {action}")
    print(f"SSSOM: {sssom_updated} updated, {sssom_dropped} withdrawn registry row")
    moved_summary = ", ".join(
        f"{count} {old}->{membership_replacements[old]}"
        for old, count in sorted(moved_edges.items())
    )
    print(f"membership: {moved_summary}")

    if not args.apply:
        print("\nDRY RUN -- pass --apply to write")
        return 0

    save_yaml(doc, COLLECTION, validate=True, target_class="IngredientCollection")
    SSSOM.write_text(sssom_text, encoding="utf-8")
    MEMBERSHIP.write_text(membership_text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Reconcile source-owned KG chemical candidates without approving identities.

The source snapshot, current native MIM review, and consumed reviewed partition
are separate authorities. Exact casefold name hits are lexical observations,
never permission to collapse source IDs or override a downstream material hold.
"""

from __future__ import annotations

import argparse
import csv
import hashlib
import io
import json
import os
from collections import Counter, defaultdict
from contextlib import ExitStack, contextmanager
from pathlib import Path

import yaml

from mediaingredientmech import ingredient_bundle_refresh
from mediaingredientmech.curie import mim_curie_for_stem
from mediaingredientmech.export.reviewed_sssom import PRODUCTS, load_review, read_sssom, row_sha256
from mediaingredientmech.synonym_policy import is_resolving_synonym


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def json_bytes(value: object) -> bytes:
    return (json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n").encode()


def relative_file(root: Path, name: str) -> Path:
    path = root / name
    if (
        Path(name).is_absolute()
        or ".." in Path(name).parts
        or not path.resolve().is_relative_to(root)
    ):
        raise ValueError(f"Snapshot path escapes root: {name}")
    if not path.is_file():
        raise ValueError(f"Missing snapshot file: {name}")
    return path


def tsv_rows(path: Path) -> list[dict]:
    with path.open(newline="") as stream:
        reader = csv.DictReader(stream, delimiter="\t", strict=True)
        if not reader.fieldnames or len(reader.fieldnames) != len(set(reader.fieldnames)):
            raise ValueError(f"Invalid TSV header: {path}")
        rows = list(reader)
    if any(None in row or any(value is None for value in row.values()) for row in rows):
        raise ValueError(f"Malformed TSV row: {path}")
    return rows


def candidate_id(candidate: dict) -> str:
    payload = [candidate[key] for key in ("source", "source_id", "category")]
    return hashlib.sha256(
        json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode()
    ).hexdigest()


OBSERVATION_FIELDS = {
    "source_record": "source_record",
    "subject": "subject",
    "source_column": "source_column",
    "source_literal": "value",
    "source_citation": "source_citation",
    "object_curie": "object",
    "predicate": "predicate",
    "relation": "relation",
    "primary_knowledge_source": "primary_knowledge_source",
    "knowledge_level": "knowledge_level",
    "agent_type": "agent_type",
    "value_encoding": "value_encoding",
}


def verify_observation_holds(holds: list[dict], observations: list[dict]) -> None:
    """Bind the entire assertion, including its predicate, not merely its ID."""
    expected = Counter(tuple(row[key] for key in OBSERVATION_FIELDS) for row in holds)
    actual = Counter(tuple(row[key] for key in OBSERVATION_FIELDS.values()) for row in observations)
    if expected != actual:
        raise ValueError("Downstream holds do not exactly match observation witnesses")


def load_snapshot(root: Path) -> tuple[dict, list[dict], dict, dict[Path, str]]:
    root = root.resolve()
    path = root / "source-manifest.json"
    manifest = json.loads(path.read_bytes())
    if manifest.get("schema_version") != 1:
        raise ValueError("Unsupported source manifest")
    hashes = {path: digest(path)}
    for name, expected in manifest["files"].items():
        item = relative_file(root, name)
        if digest(item) != expected["sha256"] or item.stat().st_size != expected["bytes"]:
            raise ValueError(f"Changed source snapshot: {name}")
        hashes[item] = expected["sha256"]

    def bound(name: str) -> Path:
        item = relative_file(root, name)
        if item not in hashes:
            raise ValueError(f"Unbound source snapshot: {name}")
        return item

    spec = manifest["candidates"]
    candidates = json.loads(bound(spec["path"]).read_bytes())
    if digest(bound(spec["path"])) != spec["sha256"] or len(candidates) != spec["rows"]:
        raise ValueError("Candidate inventory differs from source manifest")
    if dict(Counter(item["source"] for item in candidates)) != spec["counts_by_source"]:
        raise ValueError("Candidate source counts differ")
    seen = set()
    for item in candidates:
        if item["candidate_id"] != candidate_id(item) or item["candidate_id"] in seen:
            raise ValueError("Invalid or duplicate source candidate identity")
        seen.add(item["candidate_id"])
        if not item["source_id"] or not item["category"]:
            raise ValueError("Missing source ID or category")
        if any(not isinstance(item[key], str) for key in ("source_label", "raw_source_label")):
            raise ValueError("Source labels must be literal strings, including blank labels")
    holds = defaultdict(list)
    source_ids = {(item["source"], item["source_id"]) for item in candidates}
    for table in manifest["hold_tables"]:
        rows = [
            row
            for row in tsv_rows(bound(table["path"]))
            if (table["source"], row[table["source_id_field"]]) in source_ids
        ]
        if "exact_observation_witness" in table:
            verify_observation_holds(rows, tsv_rows(bound(table["exact_observation_witness"])))
        for row in rows:
            holds[(table["source"], row[table["source_id_field"]])].append(
                {"table": table["path"], "row": row}
            )
    return manifest, candidates, dict(holds), hashes


def load_consumed(root: Path, expected: dict) -> tuple[dict, dict, dict[Path, str]]:
    """Verify the coherent consumed partition; never count WITHHOLD as coverage."""
    hashes = {}
    for name in (*PRODUCTS, "manifest.json"):
        path = root / name
        hashes[path] = digest(path)
        if hashes[path] != expected["files"][name]:
            raise ValueError(f"Consumed export differs from captured source: {name}")
    manifest = json.loads((root / "manifest.json").read_bytes())
    if (
        manifest.get("schema_version") != 1
        or manifest.get("semantic_status") != "PASS_SUPPORTED_SUBSET"
    ):
        raise ValueError("Consumed export is not a reviewed supported subset")
    for name in PRODUCTS:
        if manifest["files"][name] != hashes[root / name]:
            raise ValueError("Consumed manifest product hashes differ")
    dispositions = tsv_rows(root / "mapping-dispositions.tsv")
    positions = [int(row["source_position"]) for row in dispositions]
    if sorted(positions) != list(range(1, len(positions) + 1)):
        raise ValueError("Consumed dispositions do not form a complete source partition")
    if any(row["disposition"] not in {"SUPPORTED", "WITHHOLD"} for row in dispositions):
        raise ValueError("Unknown consumed disposition")
    by_hash = defaultdict(list)
    for row in dispositions:
        by_hash[row["row_sha256"]].append(row)
    indexed = defaultdict(list)
    counts = {"source": len(dispositions)}
    for disposition, product, count_key in (
        ("SUPPORTED", PRODUCTS[0], "supported"),
        ("WITHHOLD", PRODUCTS[1], "withhold"),
    ):
        _, _, rows = read_sssom(root / product)
        expected_rows = Counter(
            row["row_sha256"] for row in dispositions if row["disposition"] == disposition
        )
        if Counter(row_sha256(row) for row in rows) != expected_rows:
            raise ValueError("Consumed partition rows differ from dispositions")
        counts[count_key] = len(rows)
        for row in rows:
            proof = [
                entry for entry in by_hash[row_sha256(row)] if entry["disposition"] == disposition
            ]
            for entry in proof:
                if any(
                    entry[key] != row[key] for key in ("subject_id", "predicate_id", "object_id")
                ):
                    raise ValueError("Consumed disposition row identity differs")
            labels = [("subject_label", row["subject_label"])]
            labels.extend(
                ("other", token.strip()) for token in row["other"].split("|") if token.strip()
            )
            for field, label in labels:
                indexed[label.casefold()].append(
                    {
                        "matched_field": field,
                        "matched_label": label,
                        "disposition": disposition,
                        "row_sha256": row_sha256(row),
                        "row": row,
                        "review_dispositions": proof,
                    }
                )
    if counts != manifest["counts"]:
        raise ValueError("Consumed partition counts differ from manifest")
    return manifest, dict(indexed), hashes


def record_paths(root: Path) -> list[Path]:
    """Native record surfaces exclude nested historical backups (#1152).

    Directory membership, not Git tracking, is authoritative: an ignored direct
    child is still a current record and must participate in reconciliation.
    """
    return sorted(
        path
        for surface in ("mapped", "unmapped")
        for path in (root / "data/ingredients" / surface).glob("*.yaml")
    )


def load_owners(root: Path, loaded: dict) -> tuple[dict, dict, dict[Path, str]]:
    native = defaultdict(list)
    for row, decision in zip(loaded["rows"], loaded["decisions"], strict=True):
        native[decision["owner_record"]].append({"row": row, "decision": decision})
    owners, index, hashes = {}, defaultdict(list), {}
    for path in record_paths(root):
        content = path.read_bytes()
        record = yaml.safe_load(content)
        name = path.relative_to(root).as_posix()
        hashes[path] = hashlib.sha256(content).hexdigest()
        if path in loaded["input_snapshot"] and hashes[path] != loaded["input_snapshot"][path]:
            raise ValueError(f"Owner changed after native review: {name}")
        owners[name] = {
            "path": name,
            "sha256": hashes[path],
            "subject_id": mim_curie_for_stem(path.stem),
            "preferred_term": record.get("preferred_term", ""),
            "identifier": record.get("identifier", ""),
            "mapping_status": record.get("mapping_status", ""),
            "ontology_mapping": record.get("ontology_mapping"),
            "native_review_rows": native[name],
        }
        label = record.get("preferred_term", "")
        if label:
            index[label.casefold()].append(
                {
                    "owner": name,
                    "kind": "preferred_term",
                    "label": label,
                    "resolving": record.get("mapping_status") != "REJECTED",
                }
            )
        for synonym in record.get("synonyms") or []:
            label = synonym.get("synonym_text", "")
            if label:
                index[label.casefold()].append(
                    {
                        "owner": name,
                        "kind": "synonym",
                        "label": label,
                        "synonym_type": synonym.get("synonym_type", ""),
                        "resolving": record.get("mapping_status") != "REJECTED"
                        and is_resolving_synonym(synonym),
                        "synonym": synonym,
                    }
                )
    return owners, dict(index), hashes


def reconcile(
    candidates: list[dict], owners: dict, index: dict, consumed: dict, holds: dict
) -> tuple[list[dict], dict]:
    ledger = []
    groups = defaultdict(list)
    for item in sorted(
        candidates, key=lambda row: (row["source"], row["source_id"], row["category"])
    ):
        hits, coverage = [], []
        for field in ("source_label", "raw_source_label"):
            label = item[field]
            if not label.strip():
                continue
            hits.extend(
                {"candidate_field": field, **hit} for hit in index.get(label.casefold(), [])
            )
            coverage.extend(
                {"candidate_field": field, **hit} for hit in consumed.get(label.casefold(), [])
            )
        matched_owners = sorted({hit["owner"] for hit in hits})
        resolving = sorted({hit["owner"] for hit in hits if hit["resolving"]})
        downstream = holds.get((item["source"], item["source_id"]), [])
        flags = []
        if not item["source_label"].strip() and not item["raw_source_label"].strip():
            flags.append("BLANK_SOURCE_LABEL")
        if downstream:
            flags.append("DOWNSTREAM_MATERIAL_HOLD")
        if len(resolving) > 1:
            flags.append("AMBIGUOUS_MULTIPLE_OWNERS")
        if hits and not resolving:
            flags.append("NON_RESOLVING_OR_REJECTED_LABEL_ONLY")
        if not hits:
            flags.append("NO_EXACT_CASEFOLD_NAME_MATCH")
        if any(owners[name]["mapping_status"] == "UNMAPPED" for name in resolving):
            flags.append("MATCHED_UNMAPPED_OWNER")
        if any(owners[name]["mapping_status"] == "AMBIGUOUS" for name in resolving):
            flags.append("MATCHED_AMBIGUOUS_OWNER")
        if any(
            entry["decision"]["disposition"] == "WITHHOLD"
            for name in resolving
            for entry in owners[name]["native_review_rows"]
        ):
            flags.append("MATCHED_OWNER_HAS_WITHHELD_MAPPINGS")
        supported = [hit for hit in coverage if hit["disposition"] == "SUPPORTED"]
        if supported:
            flags.append("CONSUMED_SUPPORTED_LEXICAL_COVERAGE")
        elif resolving:
            flags.append("MIM_NAME_NOT_IN_CONSUMED_SUPPORTED_EXPORT")
        ledger.append(
            {
                **item,
                "name_hits": hits,
                "owners": [owners[name] for name in matched_owners],
                "resolving_owner_paths": resolving,
                "consumed_name_hits": coverage,
                "downstream_holds": downstream,
                "triage_flags": flags,
                "scientific_identity_approved_by_reconciliation": False,
            }
        )
        groups[item["source_label"].casefold()].append(
            {
                key: item[key]
                for key in ("candidate_id", "source", "source_id", "category", "source_label")
            }
        )
    summary = {
        "candidate_count": len(ledger),
        "counts_by_source": dict(sorted(Counter(row["source"] for row in ledger).items())),
        "flag_counts": dict(
            sorted(Counter(flag for row in ledger for flag in row["triage_flags"]).items())
        ),
        "flag_counts_are_overlapping": True,
        "flag_counts_by_source": {
            source: dict(
                sorted(
                    Counter(
                        flag
                        for row in ledger
                        if row["source"] == source
                        for flag in row["triage_flags"]
                    ).items()
                )
            )
            for source in sorted({row["source"] for row in ledger})
        },
        "exact_casefold_label_groups": [
            {"casefold_label": label, "members": groups[label]} for label in sorted(groups)
        ],
        "grouping_is_not_identity_merging": True,
        "scientific_approval_added": False,
    }
    return ledger, summary


@contextmanager
def reserve_output_directory(output: Path):
    """Reserve an unaliased destination through retained parent handles (#1155).

    Walk from the filesystem root with O_NOFOLLOW instead of reopening an
    absolute path after a check. A replaced ancestor cannot redirect mkdir or
    publication. The caller must recheck these bindings after reserving files.
    """
    output = Path(os.path.abspath(output))
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
    with ExitStack() as stack:
        parent_fd = os.open(output.anchor, flags)
        stack.callback(os.close, parent_fd)
        bindings = []

        def verify_bindings():
            for directory_fd, component, identity in bindings:
                try:
                    actual = os.stat(component, dir_fd=directory_fd, follow_symlinks=False)
                except OSError as error:
                    raise ValueError("Output directory binding disappeared") from error
                if (actual.st_dev, actual.st_ino) != identity:
                    raise ValueError("Output directory binding changed")

        for position, component in enumerate(output.parts[1:], 1):
            verify_bindings()
            is_output = position == len(output.parts) - 1
            if is_output:
                # The leaf directory is exclusively ours; never adopt a
                # directory created by another publisher between checks.
                os.mkdir(component, dir_fd=parent_fd)
            else:
                try:
                    os.stat(component, dir_fd=parent_fd, follow_symlinks=False)
                except FileNotFoundError:
                    os.mkdir(component, dir_fd=parent_fd)
            intended = os.stat(component, dir_fd=parent_fd, follow_symlinks=False)
            identity = (intended.st_dev, intended.st_ino)
            try:
                child_fd = os.open(component, flags, dir_fd=parent_fd)
            except OSError as error:
                raise ValueError("Output directory component is aliased or unavailable") from error
            stack.callback(os.close, child_fd)
            actual = os.fstat(child_fd)
            if (actual.st_dev, actual.st_ino) != identity:
                raise ValueError("Output directory changed during acquisition")
            bindings.append((parent_fd, component, identity))
            parent_fd = child_fd
        verify_bindings()
        yield verify_bindings
        verify_bindings()


def run(
    snapshot_root: Path, mim_root: Path, review_path: Path, consumed_root: Path, output: Path
) -> dict:
    snapshot_root, mim_root, consumed_root = (
        snapshot_root.resolve(),
        mim_root.resolve(),
        consumed_root.resolve(),
    )
    manifest, candidates, holds, hashes = load_snapshot(snapshot_root)
    if output.resolve().is_relative_to(Path(manifest["upstream_root"]).resolve()):
        raise ValueError("Output must not write to the upstream checkout")
    if any(output.resolve().is_relative_to(mim_root / name) for name in ("data", "mappings")):
        raise ValueError("Output must not write under maintained MIM data surfaces")
    if output.exists() or any(parent.is_symlink() for parent in [output, *output.parents]):
        raise ValueError("Output must be a new directory without symlink parents")
    consumed_manifest, coverage, consumed_hashes = load_consumed(
        consumed_root, manifest["consumed_reviewed"]
    )
    loaded = load_review(mim_root, review_path)
    owners, index, record_hashes = load_owners(mim_root, loaded)
    ledger, summary = reconcile(candidates, owners, index, coverage, holds)
    hashes.update(consumed_hashes)
    hashes.update(loaded["input_snapshot"])
    hashes.update(record_hashes)
    hashes[Path(__file__).resolve()] = digest(Path(__file__).resolve())
    publisher = Path(ingredient_bundle_refresh.__file__).resolve()
    hashes[publisher] = digest(publisher)

    def verify_inputs():
        for path, expected in hashes.items():
            if digest(path) != expected:
                raise ValueError(f"Input changed during reconciliation: {path}")
        if set(record_hashes) != set(record_paths(mim_root)):
            raise ValueError("MIM record membership changed during reconciliation")

    verify_inputs()
    summary["mim_record_count"] = len(owners)
    summary["native_current_dispositions"] = dict(
        Counter(item["disposition"] for item in loaded["decisions"])
    )
    summary["consumed_partition_counts"] = consumed_manifest["counts"]
    summary["current_source_equals_consumed_source"] = (
        loaded["review"]["source_sha256"] == consumed_manifest["source_sha256"]
    )
    receipt = {
        "schema_version": 1,
        "source_manifest_sha256": digest(snapshot_root / "source-manifest.json"),
        "current_review_sha256": loaded["review_sha256"],
        "consumed_manifest_sha256": digest(consumed_root / "manifest.json"),
        "scientific_review": False,
        "input_hashes": {str(path): value for path, value in sorted(hashes.items())},
        "scope": "Lexical reconciliation only; preserves source IDs, predicates, native dispositions and downstream holds",
    }
    products = {"ledger.json": json_bytes(ledger), "summary.json": json_bytes(summary)}
    stream = io.StringIO(newline="")
    fields = [
        "candidate_id",
        "source",
        "source_id",
        "category",
        "source_label",
        "raw_source_label",
        "occurrences",
        "occurrences_definition",
        "triage_flags",
        "resolving_owner_paths",
    ]
    writer = csv.DictWriter(stream, fieldnames=fields, delimiter="\t", lineterminator="\n")
    writer.writeheader()
    for row in ledger:
        writer.writerow(
            {
                key: (
                    json.dumps(row[key], ensure_ascii=False)
                    if isinstance(row[key], list)
                    else row[key]
                )
                for key in fields
            }
        )
    products["ledger.tsv"] = stream.getvalue().encode()
    receipt["outputs"] = {
        name: hashlib.sha256(content).hexdigest() for name, content in products.items()
    }
    products["receipt.json"] = json_bytes(receipt)
    with reserve_output_directory(output) as verify_destination:

        def verify_publication():
            verify_destination()
            verify_inputs()

        ingredient_bundle_refresh.publish_new_files(
            [(output / name, content) for name, content in products.items()], verify_publication
        )
    return summary


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--kgm-source-snapshot-dir", type=Path, required=True)
    parser.add_argument("--mim-root", type=Path, required=True)
    parser.add_argument("--mim-review-report", type=Path, required=True)
    parser.add_argument("--consumed-reviewed-dir", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    args = parser.parse_args()
    summary = run(
        args.kgm_source_snapshot_dir,
        args.mim_root,
        args.mim_review_report,
        args.consumed_reviewed_dir,
        args.output_dir,
    )
    print(
        json.dumps(
            {key: value for key, value in summary.items() if key != "exact_casefold_label_groups"},
            indent=2,
        )
    )


if __name__ == "__main__":
    main()

"""Validate immutable Mech reviews without executing their recorded commands.

This module is the canonical, standalone payload used by CLAW and its Mechs.
The self-contained LinkML schema defines shape; the checks below enforce scope,
reference closure, provenance, and honest review/triage lifecycle semantics.
"""

from __future__ import annotations

import argparse
import hashlib
import html
import importlib
import json
import math
import os
import re
import secrets
import stat
import subprocess
import sys
import threading
from collections.abc import Sequence
from contextlib import contextmanager
from datetime import datetime, timezone
from functools import lru_cache
